window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[169]={"id":"169","numero":169,"titre":"Infections à VIH","objectifs":[{"id":"169-1","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les principales données épidémiologiques du virus de l'immunodéficience humaine (VIH)","contenu":"<p>En France, environ <strong><span class=\"kw-chiffre\">150 000 personnes</span></strong> vivent avec le <span class=\"kw-def\">VIH</span>. L'<span class=\"kw-def\">incidence</span> est estimée à <span class=\"kw-chiffre\">~6 400 nouveaux cas/an</span>, en <strong>décroissance lente</strong> grâce au <span class=\"kw-def\">TasP</span> (traitement comme prévention) et à la <span class=\"kw-ttt\">PrEP</span>. On estime à <span class=\"kw-chiffre\">~25 000</span> le nombre de personnes ignorant leur séropositivité — ce qui entretient la circulation du virus. À l'échelle mondiale, <span class=\"kw-chiffre\">~38 millions</span> de personnes sont infectées, majoritairement en <span class=\"kw-etio\">Afrique subsaharienne</span>.</p>\n      <p>La séropositivité est en <strong>baisse</strong> chez <span class=\"kw-clinique\">les</span> personnes nées en France et chez les hétérosexuels nés à l'étranger, mais en <strong>hausse</strong> chez les <span class=\"kw-etio\">HSH</span> nés à l'étranger.</p>\n      <table >\n        <thead><tr><th>Mode de contamination</th><th>Part des diagnostics (France)</th></tr></thead>\n        <tbody>\n          <tr><td>Rapports <strong>hétérosexuels</strong></td><td><span class=\"kw-chiffre\">~56 %</span> (dont ¾ nés à l'étranger, ⅓ de femmes)</td></tr>\n          <tr><td>Rapports <strong>homosexuels</strong> entre hommes (HSH)</td><td><span class=\"kw-chiffre\">~40 %</span></td></tr>\n          <tr><td>Usage de <strong>drogues injectables</strong></td><td><span class=\"kw-chiffre\">~2 %</span></td></tr>\n        </tbody>\n      </table>\n      <p>L'infection à <span class=\"kw-etio\">VIH</span> fait l'objet d'une <strong><span class=\"kw-def\">déclaration obligatoire</span></strong> à tous <span class=\"kw-clinique\">les</span> stades (séropositivité et SIDA).</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La déclaration obl<span class=\"kw-chiffre\">iga</span>toire du <span class=\"kw-etio\">VIH</span> est <strong>anonyme</strong> — on ne déclare ni l'identité ni l'adresse, contrairement à d'autres maladies à <span class=\"kw-def\">déclaration obligatoire</span> comme la <span class=\"kw-etio\">tuberculose</span>.</div>","frequence":1},{"id":"169-2","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modalités de transmission et les grands principes de prévention de la transmission du VIH","contenu":"<p>Trois liquides biologiques peuvent contenir une quantité importante de virus : <span class=\"kw-clinique\">sang</span>, <span class=\"kw-clinique\">sperme</span>, <span class=\"kw-clinique\">sécrétions vaginales</span>. Le risque de transmission se hiérarchise selon le type d'exposition.</p>\n      <table >\n        <thead><tr><th>Exposition</th><th>Risque par acte</th></tr></thead>\n        <tbody>\n          <tr><td>Rapport <strong>anal réceptif</strong> non protégé</td><td><span class=\"kw-chiffre\">~1,4 %</span> — le plus élevé</td></tr>\n          <tr><td>Rapport anal insertif non protégé</td><td><span class=\"kw-chiffre\">~0,1-0,6 %</span></td></tr>\n          <tr><td>Rapport vaginal réceptif</td><td><span class=\"kw-chiffre\">~0,08 %</span></td></tr>\n          <tr><td>Rapport vaginal insertif</td><td><span class=\"kw-chiffre\">~0,04 %</span></td></tr>\n          <tr><td>Fellation réceptive</td><td><span class=\"kw-chiffre\">~0,02 %</span></td></tr>\n          <tr><td>AES — piqûre percutanée</td><td><span class=\"kw-chiffre\">~0,3 %</span></td></tr>\n          <tr><td>Partage de seringue (UDIV)</td><td><span class=\"kw-chiffre\">~0,67 %</span></td></tr>\n          <tr><td>Transmission mère-enfant <strong>sans</strong> traitement</td><td><span class=\"kw-chiffre\">~20-25 %</span></td></tr>\n          <tr><td>TME sous <span class=\"kw-ttt\">trithérapie</span>, charge <span class=\"kw-etio\">virale</span> indétectable</td><td><span class=\"kw-chiffre\">&lt; 1 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Facteurs majorant la transmission :</strong> <span class=\"kw-alerte\">charge virale élevée</span> (<span class=\"kw-clinique\">primo-infection</span>, <span class=\"kw-def\">stade</span> SIDA), <span class=\"kw-etio\">IST associée</span> ou <span class=\"kw-clinique\">ulcération</span> génitale (<span class=\"kw-clinique\">porte d'entrée</span>), rapport anal, absence de préservatif.</p>\n      <div class=\"callout callout-info\"><strong>U = U (Undetectable = Untransmittable).</strong> Une <span class=\"kw-bio\">charge virale indétectable</span> depuis au moins <span class=\"kw-chiffre\">6 mois</span> sous traitement antirétroviral bien observé rend le risque de transmission sexuelle <strong>quasi nul</strong>, même sans préservatif. C'est le fondement du <span class=\"kw-def\">TasP</span>.</div>\n      <p><strong>Grands principes de la prévention combinée :</strong></p>\n      <ul>\n        <li><strong>Préservatif</strong> masculin ou féminin — seule protection contre <span class=\"kw-clinique\">les</span> autres <span class=\"kw-clinique\">IST</span>.</li>\n        <li><strong><span class=\"kw-ttt\">PrEP</span></strong> (prophylaxie pré-exposition) : <span class=\"kw-ttt\">ténofovir + emtricitabine</span>, en prise continue ou à la demande, chez <span class=\"kw-clinique\">les</span> personnes non infectées à haut risque (HSH ++).</li>\n        <li><strong><span class=\"kw-ttt\">TPE</span></strong> (traitement post-exposition) : <span class=\"kw-ttt\">trithérapie</span> <span class=\"kw-chiffre\">28 jours</span>, à débuter en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-alerte\">&lt; 4 h idéalement, &lt; 48 h maximum</span>.</li>\n        <li><strong><span class=\"kw-def\">Dépistage</span></strong> ciblé et élargi, matériel d'injection à usage unique, traitement universel des personnes <span class=\"kw-etio\">VIH</span>+ (TasP).</li>\n        <li><strong>Prévention de la transmission mère-enfant</strong> : <span class=\"kw-ttt\">trithérapie</span> pendant la <span class=\"kw-ci\">grossesse</span>, charge <span class=\"kw-etio\">virale</span> indétectable à l'accouchement, allaitement <span class=\"kw-ci\">contre-indiqué</span> en pays à ressources.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 23 — <span class=\"kw-ci\">Grossesse</span> normale · 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":4},{"id":"169-3","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les maladies associées au VIH hors infections opportunistes (IO)","contenu":"<p>Au-delà des infections opportunistes, le <span class=\"kw-etio\">VIH</span> expose à un sur-risque de <span class=\"kw-def\">pathologies non opportunistes</span>, liées à l'<span class=\"kw-etio\">inflammation chronique</span> résiduelle (même sous traitement) et au vieillissement accéléré.</p>\n      <p><strong>Cancers non classant SIDA</strong></p>\n      <ul>\n        <li><span class=\"kw-etio\">Cancer du canal anal</span> — lié à l'<span class=\"kw-etio\">HPV</span>, fréquent chez <span class=\"kw-clinique\">les</span> HSH ; <span class=\"kw-def\">dépistage</span> proctologique (anuscopie + cytologie anale).</li>\n        <li><span class=\"kw-etio\">Cancer bronchique</span> — <span class=\"kw-etio\">tabagisme</span> fréquent.</li>\n        <li><span class=\"kw-etio\">Hépatocarcinome</span> — en cas de co-infection <span class=\"kw-etio\">VHB</span> ou <span class=\"kw-etio\">VHC</span> ; <span class=\"kw-def\">surveillance</span> par <span class=\"kw-imagerie\">échographie</span> hépatique ± α-fœtoprotéine.</li>\n        <li><span class=\"kw-etio\">Maladie de Hodgkin</span>.</li>\n      </ul>\n      <p><strong>Autres pathologies non opportunistes</strong></p>\n      <ul>\n        <li><strong>Cardio-vasculaire :</strong> sur-risque d'<span class=\"kw-clinique\">infarctus</span> et d'<span class=\"kw-clinique\">AVC</span> (inflammation chronique + toxicité des ARV anciens).</li>\n        <li><strong>Rénal :</strong> néphropathie associée au <span class=\"kw-etio\">VIH</span> (<span class=\"kw-etio\">HIVAN</span>), tubulopathie <span class=\"kw-etio\">toxique</span> du <span class=\"kw-ttt\">ténofovir disoproxil</span>.</li>\n        <li><strong>Osseux :</strong> <span class=\"kw-clinique\">ostéopénie / ostéoporose</span> précoces.</li>\n        <li><strong>Neuro-cognitif :</strong> troubles cognitifs associés au <span class=\"kw-etio\">VIH</span> (<span class=\"kw-etio\">HAND</span>).</li>\n        <li><strong>Métabolique :</strong> insulino-résistance, <span class=\"kw-etio\">dyslipidémie</span>, lipodystrophie.</li>\n        <li><strong>Psychiatrique :</strong> <span class=\"kw-def\">dépression</span>, troubles anxieux.</li>\n      </ul>\n      <p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">IST</span> (<span class=\"kw-clinique\">syphilis</span>, gonococcie, chlamydia, condylomes) et les <span class=\"kw-etio\">pneumonies bactériennes</span> récurrentes sont également plus fréquentes — d'où une <span class=\"kw-bio\">sérologie</span> syphilis et des vaccinations (<span class=\"kw-etio\">pneumocoque</span>, hépatites) recommandées.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-etio\">cancer invasif du col de l'utérus</span> EST un cancer <strong>classant SIDA</strong> ; en revanche <span class=\"kw-clinique\">les</span> cancers <strong>anal</strong>, <strong>bronchique</strong> et l'<strong>hépatocarcinome</strong> ne le sont PAS.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 167 — Hépatites virales · 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":0},{"id":"169-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le cycle de réplication du VIH","contenu":"<p>Le <span class=\"kw-def\">VIH</span> est un <strong><span class=\"kw-def\">rétrovirus</span></strong> (genre <em>Lentivirus</em>), à ARN simple brin, enveloppé, caractérisé par une grande variabilité génomique. On distingue <span class=\"kw-def\">VIH-1</span> (pandémique, &gt;<span class=\"kw-chiffre\"> 95 %</span> des cas) et <span class=\"kw-def\">VIH-2</span> (Afrique de l'Ouest, <span class=\"kw-clinique\">évolution</span> plus lente, <span class=\"kw-ci\">résistance naturelle aux INNTI</span>).</p>\n      <p>La réplication est intense : jusqu'à <span class=\"kw-chiffre\">1 à 10 millions</span> de virions produits par jour chez une personne non traitée. Chaque étape du cycle est la cible d'une classe d'<span class=\"kw-ttt\">antirétroviraux</span>.</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Mécanisme</th><th>Classe d'ARV ciblant l'étape</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Attachement / fusion</strong></td><td>gp120 reconnaît le récepteur <span class=\"kw-bio\">CD4</span> + un co-récepteur (<span class=\"kw-bio\">CCR5</span> ou <span class=\"kw-bio\">CXCR4</span>), puis fusion membranaire</td><td><span class=\"kw-ttt\">Inhibiteurs d'entrée</span> (maraviroc, enfuvirtide)</td></tr>\n          <tr><td><strong>Transcription inverse</strong></td><td>ARN <span class=\"kw-etio\">viral</span> → ADN proviral par la <span class=\"kw-def\">transcriptase inverse</span> (étape pivot, source de variabilité)</td><td><span class=\"kw-ttt\">INTI</span> et <span class=\"kw-ttt\">INNTI</span></td></tr>\n          <tr><td><strong>Intégration</strong></td><td>ADN proviral intégré au génome de la cellule hôte par l'<span class=\"kw-def\">intégrase</span></td><td><span class=\"kw-ttt\">Inhibiteurs d'intégrase (INI)</span></td></tr>\n          <tr><td><strong>Assemblage / maturation</strong></td><td>Clivage des polyprotéines virales par la <span class=\"kw-def\">protéase</span>, libération de nouveaux virions</td><td><span class=\"kw-ttt\">Inhibiteurs de protéase (IP)</span>, toujours boostés</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Cibles cellulaires :</strong> <span class=\"kw-bio\">lymphocytes</span> <span class=\"kw-bio\">T CD4+</span> (principalement), <span class=\"kw-bio\">monocytes</span>/macrophages, cellules dendritiques et de Langerhans, microglie cérébrale. La déplétion progressive des <span class=\"kw-chiffre\">CD4</span> (apoptose directe + hyperactivation immune) se fait au rythme de <span class=\"kw-chiffre\">50-100 CD4/mm³/an</span> sans traitement.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Parce que le <span class=\"kw-etio\">VIH</span> intègre son génome dans la cellule hôte (réservoirs latents : ganglions, tissu lymphoïde digestif, SNC), la <span class=\"kw-alerte\">guérison stérilisante est impossible</span> : le traitement antirétroviral est <strong>suspensif</strong>, pas curatif — la réplication reprend à l'arrêt.</div>","frequence":0},{"id":"169-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes évocateurs de primo infection, phase chronique et SIDA","contenu":"<p>L'infection évolue en trois phases dont <span class=\"kw-clinique\">les</span> signes doivent être connus.</p>\n      <p><strong>1 · <span class=\"kw-clinique\">Primo-infection</span></strong> — survient <span class=\"kw-chiffre\">10-15 jours</span> après le contage (extrêmes 5-30 j) ; <strong>symptomatique dans ~<span class=\"kw-chiffre\">50 %</span> des cas seulement</strong>, durée <span class=\"kw-chiffre\">2-3 semaines</span>. Tableau de <span class=\"kw-etio\">syndrome rétroviral aigu</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> (<span class=\"kw-chiffre\">90 %</span>), <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">asthénie</span>, arthro-<span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">céphalées</span> — syndrome pseudo-grippal &gt; 7 j.</li>\n        <li><span class=\"kw-clinique\">Polyadénopathies</span> cervicales fermes, mobiles, indolores, symétriques (<span class=\"kw-chiffre\">75 %</span>).</li>\n        <li><span class=\"kw-clinique\">Exanthème maculo-papuleux</span> du tronc (<span class=\"kw-chiffre\">60-70 %</span>), parfois paumes-plantes.</li>\n        <li><span class=\"kw-clinique\">Pharyngite</span>, <span class=\"kw-clinique\">ulcérations buccales / génitales</span> douloureuses.</li>\n        <li>Atteinte neurologique (<span class=\"kw-chiffre\">20 %</span>) : <span class=\"kw-def\">méningite</span> lymphocytaire, polyradiculonévrite.</li>\n      </ul>\n      <p>Biologie évocatrice : <span class=\"kw-bio\">thrombopénie</span> (<span class=\"kw-chiffre\">75 %</span>), <span class=\"kw-bio\">inversion du rapport CD4/CD8</span>, <span class=\"kw-bio\">cytolyse hépatique</span>, <span class=\"kw-bio\">hypergammaglobulinémie polyclonale</span>.</p>\n      <p><strong>2 · Phase chronique</strong> — souvent asymptomatique, peut durer plusieurs années (médiane <span class=\"kw-chiffre\">~10 ans</span>). Signes d'immunodépression débutante : <span class=\"kw-etio\">candidose buccale</span>, <span class=\"kw-etio\">leucoplasie chevelue de la langue</span>, <span class=\"kw-clinique\">zona du sujet jeune</span>, dermite <span class=\"kw-clinique\">séborrhéique</span>, <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">sueurs nocturnes</span>, polyadénopathies persistantes.</p>\n      <p><strong>3 · SIDA</strong> — défini par la <strong>survenue d'une pathologie opportuniste classante</strong> ; le taux de <span class=\"kw-chiffre\">CD4</span> ne fait pas partie de la définition, mais le SIDA survient le plus souvent quand <span class=\"kw-alerte\">CD4 &lt; 200/mm³</span>. On reste définitivement au <span class=\"kw-def\">stade</span> SIDA, même après remontée des CD4 sous traitement.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Devant l'association <span class=\"kw-clinique\">fièvre + exanthème + polyadénopathies + pharyngite</span> chez un sujet à risque, évoquer une primo-<span class=\"kw-etio\">VIH</span> <strong>même si l'ELISA est négatif</strong> — la séroconversion n'est pas encore faite : on réalise une <span class=\"kw-bio\">PCR ARN-VIH</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë</em></p>","frequence":2},{"id":"169-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales affections neurologiques infectieuses et non infectieuses chez un patient au stade SIDA","contenu":"<p>L'atteinte neurologique est <strong>fréquente</strong> au <span class=\"kw-def\">stade</span> SIDA et souvent inaugurale. On la stratifie en causes infectieuses et non infectieuses.</p>\n      <p><strong>Causes infectieuses</strong></p>\n      <table >\n        <thead><tr><th>Pathologie</th><th>Seuil <span class=\"kw-chiffre\">CD4</span></th><th>Présentation · imagerie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Toxoplasmose cérébrale</span></td><td><span class=\"kw-chiffre\">&lt; 200</span></td><td>Syndrome focal + <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">céphalées</span> ; <span class=\"kw-imagerie\">IRM : abcès multiples en cocarde</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Cryptococcose neuroméningée</span></td><td><span class=\"kw-chiffre\">&lt; 100</span></td><td><span class=\"kw-def\">Méningite</span> subaiguë, <span class=\"kw-def\">syndrome méningé</span> fruste ; <span class=\"kw-bio\">antigène cryptocoque</span> sang/<span class=\"kw-bio\">LCS</span></td></tr>\n          <tr><td><span class=\"kw-etio\">LEMP</span> (virus JC)</td><td><span class=\"kw-chiffre\">&lt; 100</span></td><td>Syndrome focal progressif sans <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-imagerie\">IRM : substance blanche, pas de rehaussement ni d'œdème</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Encéphalite à CMV</span></td><td><span class=\"kw-chiffre\">&lt; 50</span></td><td>Ventriculite, myéloradiculite ; <span class=\"kw-bio\">PCR CMV</span> dans le <span class=\"kw-bio\">LCS</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Méningite tuberculeuse</span></td><td>Variable</td><td><span class=\"kw-def\">Méningite</span> subaiguë fébrile</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Causes non infectieuses</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Lymphome cérébral primitif</span> (induit par l'<span class=\"kw-etio\">EBV</span>) — <span class=\"kw-chiffre\">CD4</span> &lt; 100 ; <span class=\"kw-clinique\">masse</span> unique ou bifocale rehaussée.</li>\n        <li><span class=\"kw-def\">Encéphalite à VIH / HAND</span> — troubles cognitifs lentement progressifs (démence sous-corticale).</li>\n        <li><span class=\"kw-clinique\">Neuropathies périphériques</span> axonales douloureuses, <span class=\"kw-clinique\">myélopathie vacuolaire</span>, <span class=\"kw-clinique\">AVC</span> <span class=\"kw-etio\">ischémique</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège diagnostique.</strong> Devant une <span class=\"kw-clinique\">lésion</span> cérébrale chez un patient <span class=\"kw-etio\">VIH</span>+ avec <span class=\"kw-chiffre\">CD4</span> &lt; 100, le <span class=\"kw-def\">diagnostic différentiel</span> majeur est <span class=\"kw-etio\">toxoplasmose</span> (lésions multiples en cocarde) <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">lymphome primitif</span> (lésion unique/bifocale). On débute un <strong>traitement d'épreuve antitoxoplasme</strong> ; en l'absence de réponse clinico-radiologique à <span class=\"kw-chiffre\">J15</span>, <span class=\"kw-bio\">biopsie</span> cérébrale stéréotaxique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":0},{"id":"169-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">infections opportunistes</span> (IO) surviennent à des seuils de <span class=\"kw-bio\">CD4</span> caractéristiques : plus le taux est bas, plus la liste s'allonge. C'est le tableau-pivot de l'item.</p>\n      <table >\n        <thead><tr><th>Seuil <span class=\"kw-chiffre\">CD4</span></th><th>IO classantes à évoquer</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">&gt; 500</span></td><td>Rien de spécifique — phase asymptomatique</td></tr>\n          <tr><td><span class=\"kw-chiffre\">200-500</span></td><td><span class=\"kw-etio\">Candidose orale</span> ; <span class=\"kw-etio\">tuberculose</span> ; maladie de Kaposi ; <span class=\"kw-clinique\">zona</span> ; lymphome non hodgkinien</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&lt; 200</span></td><td><span class=\"kw-etio\">Pneumocystose pulmonaire</span> ; <span class=\"kw-etio\">toxoplasmose cérébrale</span> ; <span class=\"kw-etio\">candidose œsophagienne</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">&lt; 100</span></td><td><span class=\"kw-etio\">Cryptococcose neuroméningée</span> ; <span class=\"kw-etio\">LEMP</span> ; lymphome cérébral primitif</td></tr>\n          <tr><td><span class=\"kw-chiffre\">&lt; 50</span></td><td><span class=\"kw-etio\">Infection à CMV</span> (rétinite) ; <span class=\"kw-etio\">mycobactéries atypiques (MAC)</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Tableaux cliniques à mémoriser :</strong></p>\n      <ul>\n        <li><strong>Pneumocystose :</strong> <span class=\"kw-clinique\">toux sèche</span> + <span class=\"kw-clinique\">dyspnée progressive</span> sur <span class=\"kw-chiffre\">2-3 semaines</span> + <span class=\"kw-alerte\">hypoxémie disproportionnée</span> à une auscultation pauvre.</li>\n        <li><strong>Toxoplasmose cérébrale :</strong> <span class=\"kw-clinique\">céphalées</span> + <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">syndrome focal</span> (<span class=\"kw-clinique\">hémiparésie</span>, crise comitiale).</li>\n        <li><strong>Candidose œsophagienne :</strong> <span class=\"kw-clinique\">odynophagie</span> + muguet oral.</li>\n        <li><strong>Rétinite à <span class=\"kw-etio\">CMV</span> :</strong> <span class=\"kw-clinique\">baisse d'acuité visuelle</span> unilatérale progressive.</li>\n        <li><strong>Cryptococcose méningée :</strong> <span class=\"kw-clinique\">céphalées</span> subaiguës, <span class=\"kw-def\">syndrome méningé</span> fruste.</li>\n        <li><strong><span class=\"kw-etio\">Tuberculose</span> :</strong> formes <span class=\"kw-alerte\">extra-pulmonaires et disséminées</span> au <span class=\"kw-def\">stade</span> avancé.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte · 191 — <span class=\"kw-clinique\">Fièvre</span> chez l'immunodéprimé</em></p>","frequence":2},{"id":"169-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître le diagnostic et la prise en charge, prévention des principales IO","contenu":"<p>Chaque IO a un traitement curatif, une prophylaxie primaire (selon le seuil de <span class=\"kw-chiffre\">CD4</span>) et, le cas échéant, une prophylaxie secondaire.</p>\n      <table >\n        <thead><tr><th>IO</th><th>Traitement curatif</th><th>Prophylaxie primaire (seuil)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Pneumocystose</strong></td><td><span class=\"kw-ttt\">Cotrimoxazole</span> fortes doses ×<span class=\"kw-chiffre\"> 3 semaines</span> ± <span class=\"kw-ttt\">corticoïdes</span> si <span class=\"kw-chiffre\">PaO₂ &lt; 70 mmHg</span></td><td><span class=\"kw-ttt\">Cotrimoxazole</span> si <span class=\"kw-chiffre\">CD4 &lt; 200</span></td></tr>\n          <tr><td><strong>Toxoplasmose cérébrale</strong></td><td><span class=\"kw-ttt\">Pyriméthamine + sulfadiazine + acide folinique</span> ×<span class=\"kw-chiffre\"> 6 semaines</span></td><td><span class=\"kw-ttt\">Cotrimoxazole</span> si <span class=\"kw-chiffre\">CD4</span> &lt; 200 + <span class=\"kw-bio\">sérologie</span> toxo <span class=\"kw-chiffre\">IgG</span>+</td></tr>\n          <tr><td><strong>Candidose œsophagienne</strong></td><td><span class=\"kw-ttt\">Fluconazole</span> per os × 14-21 j</td><td>Non systématique</td></tr>\n          <tr><td><strong>Cryptococcose</strong></td><td><span class=\"kw-ttt\">Amphotéricine B + flucytosine</span> → relais <span class=\"kw-ttt\">fluconazole</span></td><td>Non recommandée</td></tr>\n          <tr><td><strong>MAC</strong></td><td><span class=\"kw-ttt\">Clarithromycine + éthambutol</span></td><td><span class=\"kw-ttt\">Azithromycine</span> si <span class=\"kw-chiffre\">CD4 &lt; 50</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">CMV</span> (rétinite)</strong></td><td><span class=\"kw-ttt\">Ganciclovir</span> IV → <span class=\"kw-ttt\">valganciclovir</span> per os</td><td><span class=\"kw-def\">Surveillance</span> si <span class=\"kw-chiffre\">CD4</span> &lt; 100 + <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">CMV</span>+</td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-clinique\">Les</span> prophylaxies sont <strong>arrêtées</strong> dès que <span class=\"kw-bio\">CD4 &gt; 200/mm³</span> pendant <span class=\"kw-chiffre\">≥ 3-6 mois</span> sous traitement antirétroviral avec charge <span class=\"kw-etio\">virale</span> indétectable.</p>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-def\">Syndrome inflammatoire</span> de restauration immunitaire (IRIS).</strong> Aggravation paradoxale d'une IO après introduction du traitement antirétroviral, par <span class=\"kw-etio\">restauration immunitaire</span>. Concerne surtout <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">cryptococcose</span>, <span class=\"kw-etio\">pneumocystose</span>, <span class=\"kw-etio\">CMV</span>.<br>Conduite : <strong>maintenir</strong> le traitement de l'IO et <span class=\"kw-clinique\">les</span> ARV ; <span class=\"kw-ttt\">corticoïdes</span> si forme sévère. <strong>Exception pneumocystose :</strong> attendre <span class=\"kw-chiffre\">~14 jours</span> de traitement efficace avant de débuter les ARV.</div>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Ne pas arrêter le <span class=\"kw-ttt\">cotrimoxazole</span> dès que <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">CD4</span> atteignent 200 : il faut <span class=\"kw-chiffre\">≥ 3-6 mois</span> de CD4 &gt; 200 sous ARV avec charge <span class=\"kw-etio\">virale</span> indétectable.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-etio\">Tuberculose</span> Enfant / Adulte</em></p>","frequence":3},{"id":"169-9","rang":"B","rubrique":"Contenu multimédia","titre":"Photographie d’un sarcome de Kaposi","contenu":"<p>Le <span class=\"kw-etio\">sarcome de Kaposi</span> est une <span class=\"kw-def\">tumeur vasculaire</span> liée au pouvoir oncogène de l'<span class=\"kw-etio\">herpèsvirus humain 8 (HHV-8)</span>, classant SIDA. Il résulte d'une prolifération de cellules fusiformes et de vaisseaux dermiques.</p>\n      <p><strong>Aspect à reconnaître :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Macules, papules, plaques ou nodules</span> de couleur <strong>violacée, rouge sombre ou brunâtre</strong>, parfois ecchymotiques.</li>\n        <li>Lésions <strong>non prurigineuses, indolores</strong>, infiltrées, pouvant confluer.</li>\n        <li>Siège : <span class=\"kw-clinique\">membres inférieurs</span>, visage, tronc, et <strong>muqueuse buccale (palais ++)</strong>.</li>\n        <li>Possible <span class=\"kw-clinique\">lymphœdème</span> associé, parfois révélateur.</li>\n      </ul>\n      <p>Le <span class=\"kw-alerte\">risque évolutif</span> est l'extension <strong>viscérale</strong> (poumon, tube digestif), favorisée par le déficit immunitaire, pouvant menacer le <span class=\"kw-alerte\">pronostic vital</span>. Diagnostic <span class=\"kw-bio\">histologique</span>. Traitement : <strong>restauration immunitaire par <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">antirétroviraux</span></strong> ; <span class=\"kw-ttt\">chimiothérapie</span> (<span class=\"kw-ttt\">doxorubicine liposomale</span>) si forme étendue ou viscérale.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/169/kaposi-cutane.png\" alt=\"Lésions cutanées nodulaires violacées de sarcome de Kaposi\" loading=\"lazy\">\n        <figcaption>Sarcome de Kaposi — nodules et plaques violacés. Source : à fournir (fiches sources EDN item 169).</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer kaposi-cutane.png dans assets/images/169/ -->\n      <div class=\"callout callout-warn\"><strong>Image à fournir.</strong> L'export Notion ne permet pas d'identifier le fichier image correspondant. Kevin déposera la photo dans <code>assets/images/169/</code> sous le nom <code>kaposi-cutane.png</code>.</div>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/neurotoxoplasmosis","label":"Radiopaedia : Neurotoxoplasmosis"},{"href":"https://radiopaedia.org/articles/lymphomas-of-the-central-nervous-system","label":"Radiopaedia : Lymphomes du SNC"},{"href":"https://radiopaedia.org/articles/progressive-multifocal-leukoencephalopathy","label":"Radiopaedia : LEMP"},{"href":"https://radiopaedia.org/articles/cytomegalovirus-encephalitis","label":"Radiopaedia : CMV encephalitis"},{"href":"https://radiopaedia.org/articles/pulmonary-pneumocystis-jirovecii-infection-2","label":"Radiopaedia : Pneumocystose pulmonaire"}]},{"id":"169-10","rang":"B","rubrique":"Contenu multimédia","titre":"Imagerie cérébrale d’une toxoplasmose","contenu":"<p>L'<span class=\"kw-imagerie\">IRM cérébrale</span> avec injection de gadolinium est l'examen de référence (supérieure au <span class=\"kw-imagerie\">scanner</span>) devant une suspicion de <span class=\"kw-etio\">toxoplasmose cérébrale</span> chez le patient immunodéprimé.</p>\n      <p><strong>Image-type à reconnaître :</strong></p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Lésions multiples</span> (typiquement 2 à 5), de taille variable.</li>\n        <li>Topographie : <span class=\"kw-imagerie\">noyaux gris centraux</span>, jonction substance grise-blanche, lobes frontaux.</li>\n        <li><strong><span class=\"kw-imagerie\">Rehaussement annulaire « en cocarde »</span></strong> après injection, centre nécrotique en hyposignal.</li>\n        <li><span class=\"kw-imagerie\">Œdème périlésionnel</span> marqué (hyposignal T1, hypersignal T2/<span class=\"kw-imagerie\">FLAIR</span>), effet de <span class=\"kw-clinique\">masse</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Diagnostic différentiel</span> :</strong> le <span class=\"kw-etio\">lymphome cérébral primitif</span> donne plutôt une <span class=\"kw-clinique\">lésion</span> <strong>unique</strong>, plus volumineuse, à rehaussement homogène. Arguments pour la toxoplasmose : lésions multiples + <span class=\"kw-chiffre\">CD4</span> &lt; 100 + <span class=\"kw-bio\">sérologie toxo IgG+</span> + réponse au traitement d'épreuve.</p>\n      <p><strong>Conduite :</strong> traitement d'épreuve par <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span> ; <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">J15</span> — amélioration = diagnostic retenu ; absence de réponse = <span class=\"kw-bio\">biopsie</span> stéréotaxique à la recherche d'un lymphome.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/169/toxoplasmose-irm-cocarde.png\" alt=\"IRM cérébrale T1 gadolinium montrant des abcès toxoplasmiques en cocarde\" loading=\"lazy\">\n        <figcaption>Toxoplasmose cérébrale — <span class=\"kw-clinique\">abcès</span> multiples en cocarde, <span class=\"kw-imagerie\">IRM</span> T1 après gadolinium. Source : à fournir (fiches sources EDN item 169).</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer toxoplasmose-<span class=\"kw-imagerie\"><span class=\"kw-imagerie\">irm</span></span>-cocarde.png dans assets/images/169/ -->\n      <div class=\"callout callout-warn\"><strong>Image à fournir.</strong> L'export Notion ne permet pas d'identifier le fichier image correspondant. Kevin déposera l'imagerie dans <code>assets/images/169/</code> sous le nom <code>toxoplasmose-<span class=\"kw-imagerie\">irm</span>-cocarde.png</code>.</div>","frequence":0},{"id":"169-11","rang":"B","rubrique":"Contenu multimédia","titre":"Imagerie pulmonaire d’une pneumocystose","contenu":"<p>La <span class=\"kw-etio\">pneumocystose</span> à <em>Pneumocystis jirovecii</em> donne une imagerie pulmonaire évocatrice. Le poumon est le <strong>seul organe touché</strong>.</p>\n      <p><strong><span class=\"kw-imagerie\">Radiographie</span> / <span class=\"kw-imagerie\">TDM</span> thoracique typique :</strong></p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Opacités interstitielles bilatérales</span>, symétriques, diffuses, à prédominance <strong>péri-hilaire</strong>.</li>\n        <li>Aspect en <strong><span class=\"kw-imagerie\">verre dépoli</span></strong> (<span class=\"kw-imagerie\">TDM</span> ++), en ailes de papillon sur la <span class=\"kw-imagerie\">radiographie</span>.</li>\n        <li>Parfois <span class=\"kw-imagerie\">kystes aériens</span>, <span class=\"kw-alerte\">pneumothorax spontané</span> (complication classique).</li>\n        <li><strong>Pas d'<span class=\"kw-imagerie\">épanchement pleural</span>, pas d'<span class=\"kw-clinique\">adénopathie</span> médiastinale</strong> (≠ pneumopathie <span class=\"kw-etio\">bactérienne</span>).</li>\n      </ul>\n      <p>Le diagnostic microbiologique repose sur le <span class=\"kw-bio\">LBA</span> (<span class=\"kw-bio\">immunofluorescence</span> ou <span class=\"kw-bio\">PCR</span>) ; <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">LDH</span> sont élevées.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Une <span class=\"kw-imagerie\">radiographie thoracique</span> <strong>normale n'exclut pas</strong> une pneumocystose (<span class=\"kw-chiffre\">20-30 %</span> des cas) : devant une forte suspicion clinique avec <span class=\"kw-alerte\">hypoxémie</span>, réaliser une <span class=\"kw-imagerie\">TDM</span> et un <span class=\"kw-bio\">LBA</span> d'emblée.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/169/pneumocystose-tdm-verre-depoli.png\" alt=\"TDM thoracique montrant des plages de verre dépoli diffuses de pneumocystose\" loading=\"lazy\">\n        <figcaption>Pneumocystose pulmonaire — plages de <span class=\"kw-imagerie\">verre dépoli</span> bilatérales diffuses. Source : à fournir (fiches sources EDN item 169).</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer pneumocystose-<span class=\"kw-imagerie\"><span class=\"kw-imagerie\">tdm</span></span>-verre-depoli.png dans assets/images/169/ -->\n      <div class=\"callout callout-warn\"><strong>Image à fournir.</strong> L'export Notion ne permet pas d'identifier le fichier image correspondant. Kevin déposera l'imagerie dans <code>assets/images/169/</code> sous le nom <code>pneumocystose-<span class=\"kw-imagerie\">tdm</span>-verre-depoli.png</code>.</div>","frequence":1},{"id":"169-12","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les principaux tests de dépistage du VIH","contenu":"<p>Le diagnostic <span class=\"kw-ttt\">biologique</span> du <span class=\"kw-etio\">VIH</span> repose sur des tests sérologiques et virologiques aux cinétiques différentes.</p>\n      <table >\n        <thead><tr><th>Test</th><th>Cible</th><th>Délai de positivité · usage</th></tr></thead>\n        <tbody>\n          <tr><td><strong>ELISA combiné</strong> 4ᵉ génération</td><td>AC anti-<span class=\"kw-etio\">VIH</span>-1 et VIH-2 + <span class=\"kw-bio\">antigène p24</span></td><td><span class=\"kw-chiffre\">~3 semaines</span> — <strong>test de <span class=\"kw-def\">dépistage</span> de référence</strong>, 1ʳᵉ intention</td></tr>\n          <tr><td><strong>Test rapide (TROD)</strong></td><td>AC anti-<span class=\"kw-etio\">VIH</span>-1 et VIH-2 seuls</td><td>Moins sensible — urgences (<span class=\"kw-def\">AES</span>, exposition sexuelle), autotest</td></tr>\n          <tr><td><strong>Western Blot</strong></td><td>AC dirigés contre <span class=\"kw-clinique\">les</span> protéines virales</td><td><strong>Test de confirmation</strong> ; incomplet en <span class=\"kw-clinique\">primo-infection</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">PCR</span> ARN-<span class=\"kw-etio\">VIH</span></strong> (charge <span class=\"kw-etio\">virale</span>)</td><td>ARN <span class=\"kw-etio\">viral</span> plasmatique</td><td>Positive dès <span class=\"kw-chiffre\">J10</span> — diagnostic en <span class=\"kw-alerte\">fenêtre sérologique</span>, <span class=\"kw-def\">suivi</span>, nouveau-né</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Algorithme diagnostique :</strong></p>\n      <ol>\n        <li><span class=\"kw-bio\">ELISA combiné</span> en 1ʳᵉ intention.</li>\n        <li>Si ELISA positif → <span class=\"kw-bio\">Western Blot</span> de confirmation sur le même prélèvement.</li>\n        <li>Si confirmé → <strong>2ᵉ prélèvement</strong> (nouvel ELISA) pour éliminer une erreur d'identité.</li>\n        <li>Si ELISA négatif mais suspicion forte de <span class=\"kw-clinique\">primo-infection</span> → <span class=\"kw-bio\">PCR ARN-VIH</span> d'emblée.</li>\n        <li>Exposition &lt;<span class=\"kw-chiffre\"> 6 semaines</span> → répéter l'ELISA à <span class=\"kw-chiffre\">6 semaines</span> (fenêtre sérologique).</li>\n        <li>Nourrisson de mère <span class=\"kw-etio\">VIH</span>+ → <span class=\"kw-bio\">PCR ARN-VIH</span> à la naissance, <span class=\"kw-chiffre\">M1</span>, M3, M6 (2 <span class=\"kw-bio\">PCR</span>+ = transmission confirmée).</li>\n      </ol>\n      <p><strong>Populations à dépister :</strong> <span class=\"kw-def\">dépistage</span> proposé au moins une fois entre <span class=\"kw-chiffre\">15 et 75 ans</span> ; populations à risque (<span class=\"kw-etio\">HSH</span>, <span class=\"kw-etio\">UDIV</span>, migrants de zone d'endémie) ; circonstances (<span class=\"kw-clinique\">IST</span>, <span class=\"kw-ci\">grossesse</span>, IVG, viol, AES, projet de contraception).</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Un <span class=\"kw-bio\">ELISA négatif</span> à J10 <strong>n'élimine pas</strong> une <span class=\"kw-clinique\">primo-infection</span> : seule la <span class=\"kw-bio\">PCR ARN-VIH</span> est positive dans <span class=\"kw-clinique\">les</span> 10 premiers jours.</div>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/169/algorithme-depistage-vih.png\" alt=\"Algorithme de dépistage et de confirmation du VIH\" loading=\"lazy\">\n        <figcaption>Stratégie diagnostique du <span class=\"kw-etio\">VIH</span> — test combiné, Western Blot, <span class=\"kw-bio\">PCR</span> ARN. Source : à fournir (fiches sources EDN item 169).</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer algorithme-depistage-vih.png dans assets/images/169/ (facultatif — l'algorithme est déjà transcrit ci-dessus) -->\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":3},{"id":"169-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’évolution des tests au cours de l’infection chronique par le VIH","contenu":"<p><span class=\"kw-clinique\">Les</span> marqueurs virologiques et sérologiques évoluent selon une cinétique caractéristique, utile au diagnostic comme au <span class=\"kw-def\">suivi</span>.</p>\n      <table >\n        <thead><tr><th>Marqueur</th><th>Apparition</th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">ARN-VIH</span> plasmatique</td><td><span class=\"kw-chiffre\">J10</span></td><td>Pic en <span class=\"kw-clinique\">primo-infection</span> puis <em>set-point</em> individuel ; <span class=\"kw-chiffre\">&lt; 50 copies/mL</span> sous traitement</td></tr>\n          <tr><td><span class=\"kw-bio\">Antigène p24</span></td><td><span class=\"kw-chiffre\">J15</span></td><td>Disparaît <span class=\"kw-chiffre\">1-2 semaines</span> après la séroconversion, réapparaît au <span class=\"kw-def\">stade</span> SIDA avancé</td></tr>\n          <tr><td><span class=\"kw-bio\">Anticorps anti-VIH</span></td><td><span class=\"kw-chiffre\">J20-J25</span></td><td>Positifs chez &gt;<span class=\"kw-chiffre\"> 99 %</span> à J42 ; persistent à vie</td></tr>\n          <tr><td><span class=\"kw-bio\">Lymphocytes CD4</span></td><td>—</td><td>Décroissance de <span class=\"kw-chiffre\">50-100/mm³/an</span> sans traitement ; remontée sous ARV</td></tr>\n        </tbody>\n      </table>\n      <p>L'augmentation des <span class=\"kw-bio\">CD8</span> en <span class=\"kw-clinique\">primo-infection</span> entraîne une <strong><span class=\"kw-bio\">inversion du rapport CD4/CD8</span></strong>, caractéristique.</p>\n      <p><strong>Bilan initial du patient <span class=\"kw-etio\">VIH</span>+ :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">CD4 / CD8</span> + <span class=\"kw-bio\">charge virale ARN-VIH</span>.</li>\n        <li><span class=\"kw-bio\">Génotype de résistance</span> avant traitement.</li>\n        <li><span class=\"kw-bio\">HLA-B*57:01</span> — sa positivité <span class=\"kw-ci\">contre-indique l'abacavir</span>.</li>\n        <li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">VHA, VHB, VHC, syphilis, toxoplasmose</span> (± <span class=\"kw-etio\">CMV</span> si <span class=\"kw-chiffre\">CD4</span> &lt; 100).</li>\n        <li><span class=\"kw-bio\">IGRA</span> (<span class=\"kw-def\">dépistage</span> de <span class=\"kw-etio\">tuberculose</span> latente), bilan métabolique, rénal, hépatique, lipidique.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Suivi</span> sous traitement :</strong> consultations à <span class=\"kw-chiffre\">M1, M3, M6, M12</span>, puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 à 6 mois</span> si <span class=\"kw-chiffre\">CD4</span> &gt; 350 et charge <span class=\"kw-etio\">virale</span> indétectable stable.</p>","frequence":0},{"id":"169-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes du traitement antirétroviral","contenu":"<p>Le <span class=\"kw-def\">traitement antirétroviral (TAR)</span> est l'objectif central de la prise en charge du <span class=\"kw-etio\">VIH</span>.</p>\n      <p><strong>Objectifs du traitement</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">Charge virale indétectable</span> (&lt; 50 copies/mL) — critère principal de succès.</li>\n        <li>Restauration immunitaire (<span class=\"kw-bio\">CD4 &gt; 500/mm³</span>).</li>\n        <li>Blocage de la transmission (<span class=\"kw-def\">TasP</span>, U=U).</li>\n        <li><span class=\"kw-clinique\">Espérance de vie</span> proche de celle de la population générale.</li>\n      </ul>\n      <p><strong>Indications — traitement universel.</strong> Tout patient diagnostiqué <span class=\"kw-etio\">VIH</span>+ doit être traité, <strong>quel que soit le taux de <span class=\"kw-chiffre\">CD4</span> et la charge <span class=\"kw-etio\">virale</span></strong>. <span class=\"kw-alerte\">Urgence</span> à initier en cas de <span class=\"kw-alerte\">primo-infection</span>, <span class=\"kw-alerte\">grossesse</span>, <span class=\"kw-alerte\">infection opportuniste en cours</span> (sauf pneumocystose sévère : différer ~14 j) ou <span class=\"kw-def\">AES</span> (<span class=\"kw-ttt\">TPE</span> &lt;<span class=\"kw-chiffre\"> 48 h</span>).</p>\n      <p><strong>Schéma de 1ʳᵉ intention :</strong> <strong><span class=\"kw-ttt\">trithérapie</span></strong> en 1 comprimé/jour, associant <span class=\"kw-ttt\">2 INTI</span> + un troisième agent — préférentiellement un <span class=\"kw-ttt\">inhibiteur d'intégrase (INI)</span> ; alternatives : 1 <span class=\"kw-ttt\">INNTI</span> ou 1 <span class=\"kw-ttt\">inhibiteur de protéase boosté</span>.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Molécules-phares</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>INTI</strong></td><td><span class=\"kw-ttt\">ténofovir</span> (TDF/TAF), <span class=\"kw-ttt\">emtricitabine</span>, <span class=\"kw-ttt\">lamivudine</span>, <span class=\"kw-ttt\">abacavir</span></td><td>TDF : <span class=\"kw-ci\">toxicité rénale tubulaire</span> ; abacavir : <span class=\"kw-ci\">CI si HLA-B*57:01+</span></td></tr>\n          <tr><td><strong>INNTI</strong></td><td><span class=\"kw-ttt\">rilpivirine</span>, <span class=\"kw-ttt\">efavirenz</span></td><td>Efavirenz : troubles neuropsychiques ; inactifs sur le <span class=\"kw-etio\">VIH</span>-2</td></tr>\n          <tr><td><strong>IP</strong></td><td><span class=\"kw-ttt\">darunavir</span>, <span class=\"kw-ttt\">atazanavir</span></td><td>Toujours boostés (ritonavir / cobicistat) ; interactions médicamenteuses ++</td></tr>\n          <tr><td><strong>INI</strong></td><td><span class=\"kw-ttt\">bictégravir</span>, <span class=\"kw-ttt\">dolutégravir</span></td><td>1ʳᵉ ligne, excellente tolérance</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Règles de prescription :</strong> initiation par un médecin hospitalier après <span class=\"kw-bio\">génotype de résistance</span> ; traitement <strong>à vie</strong> (suspensif) ; <span class=\"kw-alerte\">observance cruciale</span> (une mauvaise observance sélectionne des résistances). En cas de co-infection <span class=\"kw-etio\">VHB</span>, l'association <span class=\"kw-ttt\">ténofovir + emtricitabine</span> est active sur <span class=\"kw-clinique\">les</span> deux virus.</p>\n      <div class=\"callout callout-warn\"><strong>Piège cardinal.</strong> Le traitement antirétroviral est indiqué pour <strong>tous</strong> <span class=\"kw-clinique\">les</span> patients : le seuil historique « attendre <span class=\"kw-chiffre\">CD4</span> &lt; 500 » est <span class=\"kw-alerte\">obsolète</span> depuis 2015.</div>","frequence":5},{"id":"169-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les contre-indications vaccinales en cas d’infection chronique par le VIH","contenu":"<p>Chez le patient <span class=\"kw-etio\">VIH</span>+, le danger vient des <strong><span class=\"kw-ci\">vaccins vivants atténués</span></strong> : le germe vaccinal peut se multiplier chez un hôte immunodéprimé (<span class=\"kw-ttt\">vaccination</span>-maladie). <span class=\"kw-clinique\">Les</span> vaccins inactivés sont au contraire <strong>recommandés</strong> (risque <span class=\"kw-etio\">infectieux</span> majoré).</p>\n      <table >\n        <thead><tr><th>Vaccin</th><th>Type</th><th>Statut chez le VIH+</th></tr></thead>\n        <tbody>\n          <tr><td><strong>BCG</strong></td><td>Vivant atténué</td><td><span class=\"kw-ci\">Contre-indication absolue</span> — quel que soit le taux de <span class=\"kw-chiffre\">CD4</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span> jaune (anti-amarile)</td><td>Vivant atténué</td><td><span class=\"kw-ci\">CI si CD4 &lt; 200</span> ; possible si <span class=\"kw-chiffre\">CD4</span> &gt; 200</td></tr>\n          <tr><td><span class=\"kw-ttt\">ROR</span>, varicelle-<span class=\"kw-clinique\">zona</span></td><td>Vivant atténué</td><td><span class=\"kw-ci\">CI si CD4 &lt; 200</span> ; possible si <span class=\"kw-chiffre\">CD4</span> &gt; 200</td></tr>\n          <tr><td><span class=\"kw-etio\">Grippe</span>, <span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-def\">hépatite</span> B</td><td>Inactivé / polyosidique</td><td><strong>Recommandés systématiquement</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Hépatite</span> A, <span class=\"kw-etio\">HPV</span>, dTPolio, COVID</td><td>Inactivé</td><td>Recommandés selon le contexte</td></tr>\n        </tbody>\n      </table>\n      <p>Vaccinations <strong>systématiques</strong> chez tout patient <span class=\"kw-etio\">VIH</span>+ : <span class=\"kw-ttt\">anti-pneumococcique</span>, <span class=\"kw-ttt\">anti-grippale</span> annuelle, <span class=\"kw-ttt\">anti-hépatite B</span> (si non immunisé), rappels dTP. Vacciner de préférence quand la charge <span class=\"kw-etio\">virale</span> est indétectable et <span class=\"kw-bio\">CD4 &gt; 200/mm³</span>.</p>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-ci\">BCG</span> est <span class=\"kw-ci\">contre-indiqué</span> chez <strong>tout</strong> patient <span class=\"kw-etio\">VIH</span>+, quel que soit le taux de <span class=\"kw-chiffre\">CD4</span> — à distinguer du <span class=\"kw-ttt\">ROR</span>, qui redevient possible si CD4 &gt; 200.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":0},{"id":"169-16","rang":"A","rubrique":"Contenu multimédia","titre":"Photographie d’une candidose buccale","contenu":"<p>La <span class=\"kw-etio\">candidose buccale</span> (muguet), due le plus souvent à <span class=\"kw-etio\">Candida albicans</span>, est un signe précoce d'immunodépression chez le patient <span class=\"kw-etio\">VIH</span>+.</p>\n      <p><strong>Aspect à reconnaître :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Enduit blanc crémeux</span> sur la langue, le palais, la face interne des joues.</li>\n        <li><strong>Se détache au grattage</strong>, laissant parfois un <span class=\"kw-clinique\">érythème sous-jacent</span>.</li>\n        <li>Formes associées : <span class=\"kw-clinique\">perlèche</span> (commissures labiales), <span class=\"kw-clinique\">chéilite angulaire</span>, <span class=\"kw-clinique\">glossite</span> dépapillée.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> La candidose buccale se détache au grattage — à l'inverse de la <span class=\"kw-etio\">leucoplasie chevelue de la langue</span> (liée à l'<span class=\"kw-etio\">EBV</span>), qui <strong>ne se détache pas</strong>.</div>\n      <p>Chez le patient <span class=\"kw-etio\">VIH</span>+, elle survient dès que <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">CD4</span> baissent et doit faire <strong>rechercher une candidose œsophagienne</strong> (<span class=\"kw-clinique\">odynophagie</span>). Traitement : <span class=\"kw-ttt\">amphotéricine B</span> locale ou <span class=\"kw-ttt\">fluconazole</span> per os si forme sévère. Toute candidose buccale inexpliquée justifie un <strong><span class=\"kw-def\">dépistage</span> du VIH</strong>.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/169/candidose-buccale.png\" alt=\"Candidose buccale — enduit blanchâtre sur la langue et le palais\" loading=\"lazy\">\n        <figcaption>Candidose buccale (muguet) — enduit blanc crémeux détachable au grattage. Source : à fournir (fiches sources EDN item 169).</figcaption>\n      </figure>\n      <!-- TODO Kevin : déposer candidose-buccale.png dans assets/images/169/ -->\n      <div class=\"callout callout-warn\"><strong>Image à fournir.</strong> L'export Notion ne permet pas d'identifier le fichier image correspondant. Kevin déposera la photo dans <code>assets/images/169/</code> sous le nom <code>candidose-buccale.png</code>.</div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-ttt\">TPE</span> post-exposition :</strong> <span class=\"kw-ttt\">trithérapie</span> <span class=\"kw-chiffre\">28 j</span> à débuter <span class=\"kw-alerte\">&lt; 4 h idéalement, &lt; 48 h maximum</span> — au-delà inefficace.<br><strong>Initiation du TAR immédiate :</strong> <span class=\"kw-alerte\">primo-infection</span>, <span class=\"kw-alerte\">grossesse</span>, <span class=\"kw-alerte\">IO en cours</span> (sauf pneumocystose sévère : différer <span class=\"kw-chiffre\">~14 j</span>).<br><strong>Syndrome neurologique focal / <span class=\"kw-alerte\">encéphalite</span> :</strong> <span class=\"kw-imagerie\">imagerie cérébrale (TDM ou IRM) en urgence</span>.<br><strong>Toxoplasmose cérébrale :</strong> <span class=\"kw-ttt\">traitement d’épreuve</span> d’emblée devant des <span class=\"kw-imagerie\">abcès en cocarde</span>, réévalué à <span class=\"kw-chiffre\">J15</span>.</p>","hospit":"<p><strong>Initiation du TAR :</strong> prescription initiale réservée au <span class=\"kw-ttt\">médecin hospitalier</span> spécialiste, après <span class=\"kw-bio\">génotype de résistance</span>.<br><strong>Déclaration obl<span class=\"kw-chiffre\">iga</span>toire :</strong> <span class=\"kw-def\">anonyme</span>, à tous <span class=\"kw-clinique\">les</span> stades (séropositivité et SIDA).<br><strong>Pneumocystose :</strong> <span class=\"kw-ttt\">isolement</span> en <span class=\"kw-def\">chambre seule</span>, précautions « gouttelettes » ou « air ».<br><strong><span class=\"kw-ci\">Grossesse</span> <span class=\"kw-etio\">VIH</span>+ :</strong> <span class=\"kw-def\">suivi</span> spécialisé, prévention de la <span class=\"kw-def\">transmission mère-enfant</span> (<span class=\"kw-ttt\">trithérapie</span>, <span class=\"kw-bio\">charge virale indétectable</span> à l’accouchement, <span class=\"kw-ci\">allaitement contre-indiqué</span>).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Hypoxémie disproportionnée</span> à une auscultation pauvre, <span class=\"kw-alerte\">PaO₂ &lt; 60 mmHg</span> ou « poumons blancs » — pneumocystose grave.</li><li><span class=\"kw-alerte\">Pneumothorax spontané</span> compliquant une pneumocystose.</li><li><span class=\"kw-alerte\">Syndrome neurologique focal fébrile</span> + crise comitiale — toxoplasmose cérébrale.</li><li><span class=\"kw-alerte\">Syndrome méningé + HTIC</span> + troubles de conscience — cryptococcose neuroméningée (engage le <span class=\"kw-alerte\">pronostic vital</span>).</li><li><span class=\"kw-alerte\">Baisse d’acuité visuelle</span> / cécité par atteinte maculaire — rétinite à <span class=\"kw-etio\">CMV</span>.</li><li><span class=\"kw-alerte\">Paraplégie + troubles sphinctériens</span> (myéloradiculite à <span class=\"kw-etio\">CMV</span>) — risque de <span class=\"kw-clinique\">nécrose</span> des racines, <span class=\"kw-alerte\">urgence</span>.</li><li><span class=\"kw-alerte\">Charge virale élevée</span> (<span class=\"kw-clinique\">primo-infection</span>, <span class=\"kw-def\">stade</span> SIDA) — risque de transmission majoré.</li><li><span class=\"kw-alerte\">IRIS</span> : aggravation paradoxale d’une IO après introduction du TAR.</li></ul>","principes":"<p><strong>Traitement antirétroviral (TAR)</strong></p><ul><li>Indication : <strong>traitement universel</strong> de tout patient <span class=\"kw-etio\">VIH</span>+, <span class=\"kw-alerte\">quel que soit le taux de CD4 et la charge virale</span> (seuil « <span class=\"kw-chiffre\">CD4</span> &lt; 500 » obsolète depuis 2015).</li><li>Schéma de 1re intention : <span class=\"kw-ttt\">trithérapie</span> en 1 cp/j = <span class=\"kw-ttt\">2 INTI + 1 inhibiteur d’intégrase</span> (ex : <span class=\"kw-ttt\">bictégravir + emtricitabine + ténofovir alafénamide</span>).</li><li>Alternatives : 2 INTI + 1 <span class=\"kw-ttt\">INNTI</span> ou + 1 <span class=\"kw-ttt\">IP boosté</span>.</li><li>Traitement à vie (<strong>suspensif</strong>), <span class=\"kw-alerte\">observance cruciale</span> ; <span class=\"kw-ci\">abacavir contre-indiqué si HLA-B*57:01 positif</span>.</li><li>Co-infection <span class=\"kw-etio\">VHB</span> : <span class=\"kw-ttt\">ténofovir + emtricitabine</span> (double activité anti-<span class=\"kw-etio\">VIH</span> et anti-<span class=\"kw-etio\">VHB</span>).</li></ul><p><strong>Traitement des IO + prophylaxies</strong></p><ul><li><strong>Pneumocystose :</strong> <span class=\"kw-ttt\">cotrimoxazole</span> fortes doses × <span class=\"kw-chiffre\">3 sem</span> ± <span class=\"kw-ttt\">corticoïdes</span> si <span class=\"kw-chiffre\">PaO₂ &lt; 70 mmHg</span> ; prophylaxie primaire si <span class=\"kw-chiffre\">CD4 &lt; 200</span>.</li><li><strong>Toxoplasmose :</strong> <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span> × <span class=\"kw-chiffre\">6 sem</span> ; prophylaxie <span class=\"kw-ttt\">cotrimoxazole</span> si <span class=\"kw-chiffre\">CD4 &lt; 200</span> + <span class=\"kw-bio\">IgG+</span>.</li><li><strong>Candidose œsophagienne :</strong> <span class=\"kw-ttt\">fluconazole</span> PO × <span class=\"kw-chiffre\">14-21 j</span>.</li><li><strong>Cryptococcose :</strong> <span class=\"kw-ttt\">amphotéricine B + flucytosine</span> → relais <span class=\"kw-ttt\">fluconazole</span>.</li><li><strong><span class=\"kw-etio\">CMV</span> (rétinite) :</strong> <span class=\"kw-ttt\">ganciclovir</span> IV → <span class=\"kw-ttt\">valganciclovir</span> PO.</li><li><strong>MAC :</strong> <span class=\"kw-ttt\">clarithromycine + éthambutol</span> ; prophylaxie <span class=\"kw-ttt\">azithromycine</span> si <span class=\"kw-chiffre\">CD4 &lt; 50</span>.</li><li>Arrêt des prophylaxies : <span class=\"kw-chiffre\">CD4 &gt; 200</span> pendant <span class=\"kw-chiffre\">≥ 3-6 mois</span> sous TAR + <span class=\"kw-bio\">charge virale indétectable</span>.</li></ul><p><strong>Prévention de la transmission</strong></p><ul><li><span class=\"kw-ttt\">PrEP</span> : <span class=\"kw-ttt\">ténofovir + emtricitabine</span>, en continu ou à la demande (HSH ++).</li><li><span class=\"kw-ttt\">TPE</span> : <span class=\"kw-ttt\">trithérapie</span> <span class=\"kw-chiffre\">28 j</span>, à débuter <span class=\"kw-alerte\">&lt; 48 h</span>.</li><li>Vaccins inactivés recommandés (<span class=\"kw-ttt\">pneumocoque</span>, <span class=\"kw-ttt\">grippe</span>, <span class=\"kw-ttt\">hépatite B</span>) ; <span class=\"kw-ci\">vaccins vivants contre-indiqués</span> — <span class=\"kw-ci\">BCG contre-indiqué quel que soit le CD4</span>, <span class=\"kw-clinique\">fièvre</span> jaune / <span class=\"kw-ttt\">ROR</span> / varicelle <span class=\"kw-ci\">contre-indiqués si CD4 &lt; 200</span>.</li><li>TME : <span class=\"kw-ttt\">trithérapie</span> pendant la <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-bio\">charge virale indétectable</span> à l’accouchement, <span class=\"kw-ci\">allaitement contre-indiqué</span> en pays à ressources.</li></ul>","suivi":"<p><strong>Objectif virologique :</strong> <span class=\"kw-bio\">charge virale indétectable</span> <span class=\"kw-chiffre\">&lt; 50 copies/mL</span> en <span class=\"kw-chiffre\">3-6 mois</span>.<br><strong>Objectif immunitaire :</strong> restauration des <span class=\"kw-bio\">CD4 &gt; 500/mm³</span>.<br><strong>Rythme :</strong> consultations <span class=\"kw-chiffre\">M1, M3, M6, M12</span> puis tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3-6 mois</span> si <span class=\"kw-chiffre\">CD4</span> &gt; 350 et charge <span class=\"kw-etio\">virale</span> indétectable stable.<br><strong>Bilan annuel :</strong> <span class=\"kw-bio\">rénal, hépatique, lipidique, osseux</span> ; <span class=\"kw-bio\">frottis</span> cervical ; <span class=\"kw-def\">dépistage</span> des <span class=\"kw-etio\">IST</span>.<br><strong>Arrêt des prophylaxies IO :</strong> <span class=\"kw-chiffre\">CD4 &gt; 200</span> pendant <span class=\"kw-chiffre\">≥ 3-6 mois</span> + <span class=\"kw-bio\">charge virale</span> indétectable.</p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/infections-a-herpes-virus-du-sujet-immunocompetent-infections-par-le-vih","label":"Collège CEN — Infections herpès & VIH"},{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-169.pdf","label":"Collège Pilly — VIH (item 169, PDF)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient à risque VIH ou VIH+ connu — Quel point d’entrée ?","detail":"<h4>CAT — Patient <span class=\"kw-etio\">VIH</span> : démarche diagnostique — Exposition récente · <span class=\"kw-def\">dépistage</span> · infections opportunistes stratifiées par le taux de <span class=\"kw-chiffre\">CD4</span></h4>","branches":[{"to":"t-tpe","label":"Exposition à risque < 48 h (AES, rapport, viol)","color":"blue"},{"to":"q-diag","label":"Suspicion de primo-infection / dépistage","color":"blue"},{"to":"q-cd4","label":"VIH+ symptomatique : stratifier sur les CD4","color":"amber"}]},{"id":"t-tpe","kind":"terminal","label":"Traitement post-exposition (TPE)","color":"blue","detail":"<h4>Délai</h4><ul><li>À débuter <span class=\"kw-alerte\">&lt; 4 h idéalement, &lt; 48 h maximum</span> ; au-delà, inefficace.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ténofovir + emtricitabine + dolutégravir</span> (ou rilpivirine) pendant <span class=\"kw-chiffre\">28 jours</span>.</li><li>Indications : <span class=\"kw-etio\">AES</span>, rapport non protégé à risque, viol, partage de seringue.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-bio\">VIH / VHB / VHC</span> à la base, tolérance à <span class=\"kw-chiffre\">J15</span>, <span class=\"kw-bio\">sérologies</span> finales à <span class=\"kw-chiffre\">M2 et M4</span>.</li></ul>"},{"id":"q-diag","kind":"decision","label":"Résultat de l’ELISA combiné 4e génération","branches":[{"to":"t-confirm","label":"ELISA positif","color":"green"},{"to":"t-pcr","label":"ELISA négatif mais tableau de primo-infection","color":"amber"}]},{"id":"t-confirm","kind":"terminal","label":"Confirmer le diagnostic","color":"green","detail":"<h4>Paraclinique</h4><ul><li>Confirmation par <span class=\"kw-bio\">Western Blot</span> sur le même prélèvement.</li><li><span class=\"kw-bio\">2e prélèvement</span> (nouvel ELISA) pour éliminer une erreur d’identité.</li></ul><h4>Conduite</h4><ul><li>Bilan initial complet (<span class=\"kw-bio\">CD4 / CD8</span>, <span class=\"kw-bio\">charge virale</span>, <span class=\"kw-bio\">génotype</span>, <span class=\"kw-bio\">HLA-B*57:01</span>) puis <span class=\"kw-ttt\">trithérapie</span> — traitement universel.</li></ul>"},{"id":"t-pcr","kind":"terminal","label":"PCR ARN-VIH d’emblée","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">PCR ARN-VIH</span> plasmatique d’emblée — positive dès <span class=\"kw-chiffre\">J10</span>, en <span class=\"kw-alerte\">fenêtre sérologique</span> (l’ELISA ne se positive qu’à <span class=\"kw-chiffre\">J20-J25</span>).</li></ul><h4>Conduite</h4><ul><li>Répéter l’<span class=\"kw-bio\">ELISA</span> à <span class=\"kw-chiffre\">6 semaines</span> ; initiation <span class=\"kw-ttt\">TAR</span> immédiate si <span class=\"kw-clinique\">primo-infection</span> confirmée.</li></ul>"},{"id":"q-cd4","kind":"decision","label":"Taux de CD4 ?","branches":[{"to":"t-cd4-500","label":"CD4 200-500","color":"amber"},{"to":"q-cd4-200","label":"CD4 < 200","color":"red"},{"to":"q-cd4-100","label":"CD4 < 100","color":"red"},{"to":"q-cd4-50","label":"CD4 < 50","color":"red"}]},{"id":"t-cd4-500","kind":"terminal","label":"Infections opportunistes précoces","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Candidose orale</span> (muguet) — enduit blanc détachable au grattage.</li><li><span class=\"kw-etio\">Tuberculose</span> (formes extra-pulmonaires) ; <span class=\"kw-etio\">sarcome de Kaposi</span>, <span class=\"kw-clinique\">zona</span>, lymphome non hodgkinien.</li></ul><h4>Conduite</h4><ul><li>Toute candidose buccale inexpliquée → <span class=\"kw-bio\">dépistage VIH</span> ; rechercher une <span class=\"kw-etio\">candidose œsophagienne</span> (<span class=\"kw-clinique\">odynophagie</span>).</li></ul>"},{"id":"q-cd4-200","kind":"decision","label":"Syndrome dominant ?","branches":[{"to":"t-pjp","label":"Respiratoire : toux sèche, dyspnée, hypoxémie","color":"red"},{"to":"t-toxo","label":"Neurologique focal fébrile","color":"red"},{"to":"t-candidose","label":"Odynophagie + muguet","color":"amber"}]},{"id":"t-pjp","kind":"terminal","label":"Pneumocystose pulmonaire","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Toux sèche</span> + <span class=\"kw-clinique\">dyspnée</span> progressive sur <span class=\"kw-chiffre\">2-3 sem</span> + <span class=\"kw-alerte\">hypoxémie disproportionnée</span> à une auscultation pauvre.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM : verre dépoli</span> bilatéral diffus, sans <span class=\"kw-imagerie\">épanchement pleural</span> ni <span class=\"kw-clinique\">adénopathie</span> (<span class=\"kw-imagerie\">radiographie</span> normale dans <span class=\"kw-chiffre\">20-30 %</span>).</li><li>Diagnostic : <span class=\"kw-bio\">LBA</span> (<span class=\"kw-bio\">immunofluorescence</span> / <span class=\"kw-bio\">PCR</span>) ; <span class=\"kw-bio\">LDH</span> élevées.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Cotrimoxazole</span> fortes doses × <span class=\"kw-chiffre\">3 semaines</span> ± <span class=\"kw-ttt\">corticoïdes</span> si <span class=\"kw-chiffre\">PaO₂ &lt; 70 mmHg</span> ; <span class=\"kw-ttt\">isolement</span> en <span class=\"kw-def\">chambre seule</span>.</li></ul><h4>Délai</h4><ul><li>Différer le <span class=\"kw-ttt\">TAR</span> de <span class=\"kw-chiffre\">~14 jours</span> dans <span class=\"kw-clinique\">les</span> formes sévères (limiter l’IRIS pulmonaire).</li></ul>"},{"id":"t-toxo","kind":"terminal","label":"Toxoplasmose cérébrale","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Céphalées</span> + <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">syndrome focal</span> (hémiparésie, crise comitiale).</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM / TDM en urgence</span> : <span class=\"kw-imagerie\">abcès multiples en cocarde</span>, <span class=\"kw-clinique\">œdème</span> périlésionnel, noyaux gris centraux.</li><li><span class=\"kw-bio\">Sérologie toxo IgG</span> (de valeur surtout si négative) ; <span class=\"kw-bio\">PCR Toxoplasma sur LCS</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Pyriméthamine + sulfadiazine + acide folinique</span> × 6 sem (ou <span class=\"kw-ttt\">clindamycine</span> si <span class=\"kw-ci\">allergie</span> aux <span class=\"kw-ttt\">sulfamides</span>) ; <span class=\"kw-def\">réévaluation</span> à <span class=\"kw-chiffre\">J15</span> — pas de réponse → <span class=\"kw-bio\">biopsie stéréotaxique</span> (lymphome ?).</li></ul>"},{"id":"t-candidose","kind":"terminal","label":"Candidose œsophagienne","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Odynophagie</span> + <span class=\"kw-clinique\">muguet</span> oral ; à la <span class=\"kw-imagerie\">FOGD</span> : <span class=\"kw-clinique\">dépôts blanchâtres</span> sur muqueuse érythémateuse.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Fluconazole</span> PO × <span class=\"kw-chiffre\">14-21 j</span> ; pas de prophylaxie (ni primaire ni secondaire).</li></ul>"},{"id":"q-cd4-100","kind":"decision","label":"Tableau neurologique ?","branches":[{"to":"t-crypto","label":"Méningite subaiguë / HTIC","color":"red"},{"to":"t-lemp","label":"Syndrome focal progressif sans fièvre","color":"amber"},{"to":"t-lymphome","label":"Lésion cérébrale unique","color":"amber"}]},{"id":"t-crypto","kind":"terminal","label":"Cryptococcose neuroméningée","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Céphalées</span> + <span class=\"kw-clinique\">fièvre</span> subaiguës, <span class=\"kw-def\">syndrome méningé</span> fruste, <span class=\"kw-alerte\">HTIC</span> ; engage le <span class=\"kw-alerte\">pronostic vital</span>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Antigène cryptococcique</span> sang et <span class=\"kw-bio\">LCS</span>, <span class=\"kw-bio\">encre de Chine</span> + culture (Sabouraud) ; imagerie cérébrale souvent normale.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Amphotéricine B liposomale + flucytosine</span> <span class=\"kw-chiffre\">≥ 2</span> sem → relais <span class=\"kw-ttt\">fluconazole</span> × 6 sem.</li><li><span class=\"kw-ttt\">PL évacuatrices</span> si pression &gt; <span class=\"kw-chiffre\">25 cmH₂O</span> ; différer le <span class=\"kw-ttt\">TAR</span> de <span class=\"kw-chiffre\">4-6 semaines</span>.</li></ul>"},{"id":"t-lemp","kind":"terminal","label":"LEMP (virus JC)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Syndrome focal progressif</span> + troubles cognitifs ; signes négatifs : <span class=\"kw-alerte\">pas de fièvre, pas d’HTIC, pas de céphalée</span>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM : substance blanche</span>, hypoT1 / hyperT2-FLAIR, sans rehaussement ni <span class=\"kw-clinique\">œdème</span> ; <span class=\"kw-bio\">PCR virus JC</span> dans le <span class=\"kw-bio\">LCS</span>.</li></ul><h4>Traitement</h4><ul><li>Pas de traitement <span class=\"kw-ttt\">antiviral</span> spécifique : <span class=\"kw-ttt\">restauration immunitaire par le TAR</span>.</li></ul>"},{"id":"t-lymphome","kind":"terminal","label":"Lymphome cérébral primitif","color":"amber","detail":"<h4>Clinique</h4><ul><li>Installation insidieuse : <span class=\"kw-clinique\">céphalées</span>, troubles mnésiques, confusion, puis signes de localisation ; <span class=\"kw-etio\">EBV</span>-induit.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM : lésion unique ou bifocale</span> rehaussée — <span class=\"kw-def\">diagnostic différentiel</span> majeur avec la <span class=\"kw-etio\">toxoplasmose</span> (lésions multiples).</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-bio\">Biopsie stéréotaxique</span> si échec du traitement d’épreuve antitoxoplasme à <span class=\"kw-chiffre\">J15</span> ; <span class=\"kw-ci\">éviter la corticothérapie</span> avant la <span class=\"kw-ttt\">biopsie</span> (<span class=\"kw-bio\">histologie</span> ininterprétable).</li></ul>"},{"id":"q-cd4-50","kind":"decision","label":"Atteinte dominante ?","branches":[{"to":"t-cmv","label":"Baisse d’acuité visuelle","color":"red"},{"to":"t-mac","label":"Fièvre prolongée + AEG + diarrhée","color":"amber"}]},{"id":"t-cmv","kind":"terminal","label":"Rétinite à CMV","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Baisse d’acuité visuelle</span> unilatérale progressive ; <span class=\"kw-alerte\">cécité si atteinte de la macula</span>.</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Fond d’œil</span> : lésions hémorragiques et foyers blanchâtres ; <span class=\"kw-bio\">PCR CMV</span> sang (si <span class=\"kw-bio\">IgG+</span>) ± <span class=\"kw-bio\">LCS</span> si atteinte neurologique.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Ganciclovir</span> IV ou <span class=\"kw-ttt\">foscarnet</span> IV → relais <span class=\"kw-ttt\">valganciclovir</span> PO ; maintien jusqu’à <span class=\"kw-chiffre\">CD4 &gt; 100</span> <span class=\"kw-chiffre\">≥ 6 mois</span>.</li></ul>"},{"id":"t-mac","kind":"terminal","label":"Mycobactéries atypiques (MAC)","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Fièvre</span> prolongée + <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">sueurs nocturnes</span> ; infection <span class=\"kw-clinique\">disséminée</span> (hépatosplénique, ganglionnaire, médullaire).</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Hémocultures</span> sur milieu spécifique, <span class=\"kw-bio\">LBA</span>, biopsies ; <span class=\"kw-bio\">cytopénies</span>, granulomatose.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Clarithromycine + éthambutol</span> ; prophylaxie primaire <span class=\"kw-ttt\">azithromycine</span> si <span class=\"kw-chiffre\">CD4 &lt; 50</span>.</li></ul>"}]},"cards":[{"i":"39a3698c4568","n":169,"o":"169-1","u":"Epidémiologie","t":"Connaître les principales données épidémiologiques du virus de l'immunodéficience humaine (VIH)","q":"Quelle est l'incidence annuelle du VIH en France et par quels moyens est-elle en décroissance selon les données épidémiologiques ?","a":"<p>L'incidence annuelle du VIH en France est estimée à environ <strong>6 400 nouveaux cas par an</strong>. Elle est en décroissance lente grâce au <strong>TasP</strong> (traitement comme prévention) et à la <strong>PrEP</strong>.</p>"},{"i":"8e9550f76111","n":169,"o":"169-1","u":"Epidémiologie","t":"Connaître les principales données épidémiologiques du virus de l'immunodéficience humaine (VIH)","q":"Quels sont les principaux modes de contamination du VIH en France et leur répartition en pourcentage des diagnostics ?","a":"<ul><li><strong>Rapports hétérosexuels</strong> : environ <strong>56 %</strong> des diagnostics (dont 3/4 concernent des personnes nées à l'étranger et 1/3 des femmes).</li><li><strong>Rapports homosexuels entre hommes (HSH)</strong> : environ <strong>40 %</strong> des diagnostics.</li><li><strong>Usage de drogues injectables</strong> : environ <strong>2 %</strong> des diagnostics.</li></ul>"},{"i":"9012a9fd7446","n":169,"o":"169-1","u":"Epidémiologie","t":"Connaître les principales données épidémiologiques du virus de l'immunodéficience humaine (VIH)","q":"L'infection à VIH est-elle une maladie à déclaration obligatoire en France ? Si oui, quelles sont les particularités de cette déclaration ?","a":"<p>Oui, l'infection à VIH fait l'objet d'une <strong>déclaration obligatoire</strong> à tous les stades (séropositivité et SIDA). La particularité est que cette déclaration est <strong>anonyme</strong>, c'est-à-dire que ni l'identité ni l'adresse du patient ne sont déclarées.</p>"},{"i":"b5c8213b3c2c","n":169,"o":"169-1","u":"Epidémiologie","t":"Connaître les principales données épidémiologiques du virus de l'immunodéficience humaine (VIH)","q":"Selon les données épidémiologiques en France, comment évolue la séropositivité VIH dans différentes populations spécifiques ?","a":"<p>La séropositivité VIH est <strong>en baisse</strong> chez les personnes nées en France et chez les hétérosexuels nés à l'étranger. En revanche, elle est <strong>en hausse</strong> chez les HSH (hommes ayant des relations sexuelles avec des hommes) nés à l'étranger.</p>"},{"i":"64eeb20eb4b7","n":169,"o":"169-12","u":"Examens complémentaires","t":"Connaître les principaux tests de dépistage du VIH","q":"Dans quelles situations la PCR ARN-VIH est-elle utilisée pour le diagnostic du VIH ?","a":"<p>La PCR ARN-VIH est utilisée pour le diagnostic dans plusieurs situations :</p><ul><li>Lors d'une <strong>forte suspicion de primo-infection</strong> si l'ELISA est négatif.</li><li>Pour le diagnostic dans la <strong>fenêtre sérologique</strong>, car elle est positive <strong>dès J10</strong>.</li><li>Pour le <strong>suivi</strong> de l'infection.</li><li>Pour le diagnostic chez le <strong>nouveau-né</strong> de mère VIH positive.</li></ul>"},{"i":"690b4f4fcc3d","n":169,"o":"169-12","u":"Examens complémentaires","t":"Connaître les principaux tests de dépistage du VIH","q":"Quelle est la chronologie du dépistage du VIH chez le nourrisson né d'une mère VIH positive ?","a":"<p>Chez le nourrisson de mère VIH positive, la stratégie de dépistage repose sur la <strong>PCR ARN-VIH</strong> réalisée à la <strong>naissance</strong>, puis à <strong>M1</strong>, <strong>M3</strong> et <strong>M6</strong>. Deux PCR positives confirment la transmission.</p>"},{"i":"83e54730de05","n":169,"o":"169-12","u":"Examens complémentaires","t":"Connaître les principaux tests de dépistage du VIH","q":"Quel est le test de dépistage de première intention du VIH et quelle est sa cible diagnostique ?","a":"<p>Le test de dépistage de première intention du VIH est l'<strong>ELISA combiné de 4ème génération</strong>. Il cible les <strong>anticorps anti-VIH-1 et VIH-2</strong>, ainsi que l'<strong>antigène p24</strong>.</p>"},{"i":"b72b41e9e95d","n":169,"o":"169-12","u":"Examens complémentaires","t":"Connaître les principaux tests de dépistage du VIH","q":"Dans quel délai l'ELISA combiné de 4ème génération devient-il positif après une infection par le VIH, et quel est son rôle principal ?","a":"<p>L'ELISA combiné de 4ème génération devient positif autour de <strong>3 semaines</strong> après l'infection. C'est le <strong>test de dépistage de référence</strong> en première intention.</p>"},{"i":"c01e515fd8d0","n":169,"o":"169-12","u":"Examens complémentaires","t":"Connaître les principaux tests de dépistage du VIH","q":"Quel est le piège diagnostique classique concernant l'ELISA en début d'infection par le VIH ?","a":"<p>Le piège classique est qu'un <strong>ELISA négatif à J10 n'élimine pas une primo-infection</strong>. Dans les 10 premiers jours suivant l'exposition, <strong>seule la PCR ARN-VIH est positive</strong>.</p>"},{"i":"c3978a6d5345","n":169,"o":"169-12","u":"Examens complémentaires","t":"Connaître les principaux tests de dépistage du VIH","q":"Quel test est utilisé pour la confirmation d'un diagnostic d'infection par le VIH après un ELISA positif, et quelle est sa limite ?","a":"<p>Après un ELISA positif, le <strong>Western Blot</strong> est utilisé pour la confirmation. Sa limite est qu'il peut être <strong>incomplet en primo-infection</strong>.</p>"},{"i":"ee57c7918849","n":169,"o":"169-14","u":"Prise en charge","t":"Connaître les grands principes du traitement antirétroviral","q":"Quels sont les objectifs principaux du traitement antirétroviral (TAR) chez un patient infecté par le VIH ?","a":"<p>Les objectifs principaux du TAR sont :</p><ul><li>Atteindre une charge virale <strong>indétectable</strong> (&lt; 50 copies/mL).</li><li>Restaurer l'immunité (taux de <strong>CD4 &gt; 500/mm³</strong>).</li><li>Bloquer la transmission du virus (concept de <strong>TasP / U=U</strong>).</li><li>Permettre une espérance de vie <strong>proche de celle de la population générale</strong>.</li></ul>"},{"i":"fef475ae8b47","n":169,"o":"169-14","u":"Prise en charge","t":"Connaître les grands principes du traitement antirétroviral","q":"Dans quelles situations particulières l'initiation du traitement antirétroviral (TAR) est-elle considérée comme urgente chez un patient VIH positif ?","a":"<p>L'initiation du TAR est urgente dans les situations suivantes :</p><ul><li><strong>Primo-infection</strong>.</li><li><strong>Grossesse</strong>.</li><li>Présence d'une <strong>infection opportuniste en cours</strong> (sauf pneumocystose sévère, où il faut différer d'environ 14 jours).</li><li>Après une <strong>Exposition Accidentelle au Sang (AES)</strong>, le traitement post-exposition (TPE) devant être initié dans les <strong>48 heures</strong>.</li></ul>"},{"i":"ff8f89828181","n":169,"o":"169-14","u":"Prise en charge","t":"Connaître les grands principes du traitement antirétroviral","q":"Quelle est la composition de première intention d'un schéma de traitement antirétroviral (TAR) et quels sont les molécules-phares de chaque classe ?","a":"<p>Le schéma de TAR de première intention est une <strong>trithérapie en 1 comprimé/jour</strong>, associant :</p><ul><li><strong>2 Inhibiteurs Nucléosidiques de la Transcriptase Inverse (INTI)</strong>. Molécules-phares : <ul><li><strong>ténofovir (TDF/TAF)</strong></li><li><strong>emtricitabine</strong></li><li><strong>lamivudine</strong></li><li><strong>abacavir</strong> (contre-indiqué si HLA-B*57:01+)</li></ul></li><li>Un <strong>troisième agent</strong>, préférentiellement un <strong>Inhibiteur d'Intégrase (INI)</strong>. Molécules-phares : <ul><li><strong>bictégravir</strong></li><li><strong>dolutégravir</strong></li></ul></li></ul><p>Des alternatives pour le troisième agent incluent un Inhibiteur Non-Nucléosidique de la Transcriptase Inverse (INNTI) comme la <strong>rilpivirine</strong> ou l'<strong>efavirenz</strong>, ou un Inhibiteur de Protéase <strong>boosté</strong> (darunavir, atazanavir).</p>"},{"i":"1f997bca07f4","n":169,"o":"169-15","u":"Prise en charge","t":"Connaître les contre-indications vaccinales en cas d’infection chronique par le VIH","q":"Quelles sont les contre-indications vaccinales absolues chez un patient infecté par le VIH, quel que soit son statut immunitaire ?","a":"<ul><li>Le vaccin <strong>BCG</strong> est absolument contre-indiqué chez tout patient VIH+, quel que soit le taux de CD4.</li></ul>"},{"i":"39652a557300","n":169,"o":"169-15","u":"Prise en charge","t":"Connaître les contre-indications vaccinales en cas d’infection chronique par le VIH","q":"Quels sont les vaccins systématiquement recommandés chez un patient infecté par le VIH ?","a":"<ul><li>Les vaccins <strong>anti-pneumococcique</strong>, <strong>anti-grippal annuel</strong>, <strong>anti-hépatite B</strong> (si non immunisé) et les rappels <strong>DTPolio</strong> sont systématiquement recommandés.</li><li>Les vaccinations doivent être réalisées de préférence lorsque la charge virale est <strong>indétectable</strong> et les <strong>CD4 > 200/mm³</strong>.</li></ul>"},{"i":"5a892a9303d5","n":169,"o":"169-15","u":"Prise en charge","t":"Connaître les contre-indications vaccinales en cas d’infection chronique par le VIH","q":"Quelle est la règle générale concernant l'utilisation des vaccins chez un patient infecté par le VIH ?","a":"<p>Chez le patient VIH+, les <strong>vaccins vivants atténués</strong> sont à risque élevé (multiplication du germe vaccinal chez un hôte immunodéprimé), tandis que les <strong>vaccins inactivés</strong> sont généralement recommandés en raison d'un risque infectieux majoré associé à la pathologie.</p>"},{"i":"fe0cd6fe5976","n":169,"o":"169-15","u":"Prise en charge","t":"Connaître les contre-indications vaccinales en cas d’infection chronique par le VIH","q":"Sous quelles conditions les vaccins vivants atténués comme le ROR ou la fièvre jaune peuvent-ils être envisagés chez un patient infecté par le VIH ?","a":"<ul><li>Les vaccins vivants atténués tels que le <strong>ROR</strong>, le <strong>vaccin contre la varicelle-zona</strong> et le vaccin contre la <strong>fièvre jaune</strong> sont contre-indiqués si le taux de <strong>CD4 est inférieur à 200/mm³</strong>.</li><li>Ils peuvent être envisagés, si indiqué, si le taux de <strong>CD4 est supérieur à 200/mm³</strong>.</li></ul>"},{"i":"38d6cf8715fc","n":169,"o":"169-16","u":"Contenu multimédia","t":"Photographie d’une candidose buccale","q":"Quelles sont les formes associées de candidose buccale à rechercher ?","a":"<ul><li>La <strong>perlèche</strong> au niveau des commissures labiales.</li><li>La <strong>chéilite angulaire</strong>.</li><li>La <strong>glossite dépapillée</strong>.</li></ul>"},{"i":"4a9912265ab2","n":169,"o":"169-16","u":"Contenu multimédia","t":"Photographie d’une candidose buccale","q":"Quelle conduite tenir devant toute candidose buccale inexpliquée ?","a":"<p>Toute candidose buccale inexpliquée doit faire rechercher une <strong>immunodépression</strong> et justifie un <strong>dépistage du VIH</strong>.</p>"},{"i":"8eb0d2203763","n":169,"o":"169-16","u":"Contenu multimédia","t":"Photographie d’une candidose buccale","q":"Quel est le principal diagnostic différentiel de la candidose buccale et comment les différencier ?","a":"<p>Le principal diagnostic différentiel est la <strong>leucoplasie chevelue de la langue</strong>, qui est liée au virus d'Epstein-Barr (EBV). La distinction clé réside dans le fait que la candidose buccale <strong>se détache au grattage</strong>, alors que la leucoplasie chevelue ne se détache pas.</p>"},{"i":"c25e3c187f89","n":169,"o":"169-16","u":"Contenu multimédia","t":"Photographie d’une candidose buccale","q":"Comment se présente cliniquement une candidose buccale chez un patient VIH+ ?","a":"<p>La candidose buccale se manifeste par un <strong>enduit blanc crémeux</strong>, localisé sur la langue, le palais ou la face interne des joues. Cet enduit est caractéristique car il <strong>se détache facilement au grattage</strong>, laissant parfois apparaître un érythème sous-jacent.</p>"},{"i":"d5ed9a4141f7","n":169,"o":"169-16","u":"Contenu multimédia","t":"Photographie d’une candidose buccale","q":"Quelle est la prise en charge thérapeutique de la candidose buccale chez le patient VIH+ ?","a":"<p>Le traitement repose sur l'<strong>amphotéricine B locale</strong>. En cas de forme sévère, un traitement par <strong>fluconazole per os</strong> peut être envisagé.</p>"},{"i":"02c41e99ceee","n":169,"o":"169-2","u":"Epidémiologie","t":"Connaître les modalités de transmission et les grands principes de prévention de la transmission du VIH","q":"Quels sont les liquides biologiques contenant une quantité importante de VIH et quels sont les trois modes de transmission principaux du VIH ?","a":"<p>Les liquides biologiques contenant une quantité importante de VIH sont le <strong>sang</strong>, le <strong>sperme</strong> et les <strong>sécrétions vaginales</strong>. Les trois modes de transmission principaux sont :</p><ul><li>La <strong>transmission sexuelle</strong> (rapports anaux, vaginaux, fellation).</li><li>La <strong>transmission sanguine</strong> (partage de seringues, Accident d'Exposition au Sang - AES).</li><li>La <strong>transmission materno-fœtale</strong> (pendant la grossesse, l'accouchement ou l'allaitement).</li></ul>"},{"i":"02f1cae43eaa","n":169,"o":"169-2","u":"Epidémiologie","t":"Connaître les modalités de transmission et les grands principes de prévention de la transmission du VIH","q":"Comment prévenir la transmission mère-enfant (TME) du VIH ?","a":"<p>La prévention de la transmission mère-enfant du VIH repose sur :</p><ul><li>La mise sous <strong>trithérapie de la mère pendant la grossesse</strong>.</li><li>L'atteinte d'une <strong>charge virale indétectable à l'accouchement</strong>.</li><li>La <strong>contre-indication de l'allaitement</strong> dans les pays à ressources où des alternatives sûres sont disponibles.</li></ul>"},{"i":"a9e0e6739228","n":169,"o":"169-2","u":"Epidémiologie","t":"Connaître les modalités de transmission et les grands principes de prévention de la transmission du VIH","q":"Qu'est-ce que le principe 'U=U' (Undetectable = Untransmittable) concernant la transmission du VIH, et quelle est son implication clinique ?","a":"<p>Le principe « <strong>U=U</strong> » signifie « Undetectable = Untransmittable » (Indétectable = Intransmissible). Il stipule qu'une personne vivant avec le VIH, sous traitement antirétroviral bien observé, avec une <strong>charge virale indétectable depuis au moins 6 mois</strong>, a un risque de transmission sexuelle du VIH <strong>quasi nul</strong>, même sans utilisation de préservatif. C'est le fondement du Traitement comme Prévention (TasP).</p>"},{"i":"ae05d882d10d","n":169,"o":"169-2","u":"Epidémiologie","t":"Connaître les modalités de transmission et les grands principes de prévention de la transmission du VIH","q":"Quels sont les facteurs majeurs augmentant le risque de transmission sexuelle du VIH ?","a":"<p>Les facteurs majeurs augmentant le risque de transmission sexuelle du VIH sont :</p><ul><li>La <strong>charge virale élevée</strong> (notamment lors de la primo-infection ou au stade SIDA).</li><li>La présence d'une <strong>IST associée</strong> ou d'une <strong>ulcération génitale</strong> (qui constituent une porte d'entrée).</li><li>Le <strong>rapport anal</strong> (qui présente un risque plus élevé).</li><li>L'<strong>absence de préservatif</strong>.</li></ul>"},{"i":"fdc36efa75c4","n":169,"o":"169-2","u":"Epidémiologie","t":"Connaître les modalités de transmission et les grands principes de prévention de la transmission du VIH","q":"Quelles sont les stratégies de prévention combinée de la transmission du VIH ?","a":"<p>Les stratégies de prévention combinée de la transmission du VIH incluent :</p><ul><li>L'utilisation du <strong>préservatif</strong> masculin ou féminin (seule protection contre les autres IST).</li><li>La <strong>PrEP</strong> (prophylaxie pré-exposition) : association de <strong>ténofovir + emtricitabine</strong>, en prise continue ou à la demande, chez les personnes non infectées à haut risque.</li><li>Le <strong>TPE</strong> (traitement post-exposition) : <strong>trithérapie de 28 jours</strong>, à débuter en urgence <strong>< 4 heures</strong> idéalement, et au maximum < 48 heures après l'exposition.</li><li>Le <strong>dépistage</strong> ciblé et élargi.</li><li>L'utilisation de matériel d'injection à <strong>usage unique</strong>.</li><li>Le <strong>traitement universel</strong> des personnes VIH+ (TasP).</p>"},{"i":"1a6c7657b6eb","n":169,"o":"169-3","u":"Epidémiologie","t":"Connaître les maladies associées au VIH hors infections opportunistes (IO)","q":"Quels sont les cancers non classant SIDA associés à l'infection par le VIH, et leurs spécificités ?","a":"<ul><li>Le <strong>cancer du canal anal</strong> : lié à l'<strong>HPV</strong>, fréquent chez les HSH ; dépistage proctologique par <strong>anuscopie et cytologie anale</strong>.</li><li>Le <strong>cancer bronchique</strong> : favorisé par la fréquence du tabagisme chez les patients VIH.</li><li>L'<strong>hépatocarcinome</strong> : en cas de co-infection <strong>VHB ou VHC</strong> ; surveillance par <strong>échographie hépatique ± α-fœtoprotéine</strong>.</li><li>La <strong>maladie de Hodgkin</strong>.</li></ul>"},{"i":"2c0df84bb2ca","n":169,"o":"169-3","u":"Epidémiologie","t":"Connaître les maladies associées au VIH hors infections opportunistes (IO)","q":"Quelles sont les principales pathologies non opportunistes, autres que les cancers, associées au VIH ?","a":"<ul><li><strong>Cardio-vasculaires</strong> : sur-risque d'<strong>infarctus et d'AVC</strong>.</li><li><strong>Rénales</strong> : <strong>néphropathie associée au VIH (HIVAN)</strong>, <strong>tubulopathie toxique du ténofovir disoproxil</strong>.</li><li><strong>Osseuses</strong> : <strong>ostéopénie / ostéoporose précoces</strong>.</li><li><strong>Neuro-cognitives</strong> : <strong>troubles cognitifs associés au VIH (HAND)</strong>.</li><li><strong>Métaboliques</strong> : <strong>insulino-résistance, dyslipidémie, lipodystrophie</strong>.</li><li><strong>Psychiatriques</strong> : <strong>dépression, troubles anxieux</strong>.</li><li>Enfin, les <strong>IST</strong> (syphilis, gonococcie, chlamydia, condylomes) et les <strong>pneumonies bactériennes récurrentes</strong> sont également plus fréquentes.</li></ul>"},{"i":"44d3a80ad050","n":169,"o":"169-3","u":"Epidémiologie","t":"Connaître les maladies associées au VIH hors infections opportunistes (IO)","q":"Quel cancer est classant SIDA et ne doit pas être confondu avec les cancers non classant SIDA chez le patient infecté par le VIH ?","a":"<p>Le <strong>cancer invasif du col de l'utérus</strong> est un cancer <strong>classant SIDA</strong>. Il ne doit pas être confondu avec les cancers du canal anal, bronchique et l'hépatocarcinome qui, bien qu'associés au VIH, ne sont pas classant SIDA.</p>"},{"i":"ab3ff24ce711","n":169,"o":"169-3","u":"Epidémiologie","t":"Connaître les maladies associées au VIH hors infections opportunistes (IO)","q":"Pourquoi, en dehors des infections opportunistes, le VIH expose-t-il à un sur-risque de pathologies non opportunistes ?","a":"<p>Le VIH expose à un sur-risque de pathologies non opportunistes en raison de l'<strong>inflammation chronique résiduelle</strong> (même sous traitement) et du <strong>vieillissement accéléré</strong> qu'il engendre.</p>"},{"i":"317ab17b5ed7","n":169,"o":"169-5","u":"Diagnostic positif","t":"Connaître les signes évocateurs de primo infection, phase chronique et SIDA","q":"Quels sont les signes cliniques évocateurs de la phase de primo-infection du VIH ?","a":"<p>La phase de primo-infection du VIH peut se manifester par :</p><ul><li>Un <strong>syndrome pseudo-grippal</strong> (> 7j) comprenant fièvre (90%), sueurs, asthénie, arthro-myalgies, céphalées.</li><li>Des <strong>polyadénopathies cervicales</strong> (75%), fermes, mobiles, indolores, symétriques.</li><li>Un <strong>exanthème maculo-papuleux</strong> (60-70%) du tronc, parfois palmo-plantaire.</li><li>Une <strong>pharyngite</strong> et des ulcérations buccales/génitales douloureuses.</li><li>Une atteinte neurologique (20%) comme une méningite lymphocytaire ou une polyradiculonévrite.</li></ul>"},{"i":"3b9329309b4c","n":169,"o":"169-5","u":"Diagnostic positif","t":"Connaître les signes évocateurs de primo infection, phase chronique et SIDA","q":"Comment est défini le stade SIDA dans l'infection à VIH ?","a":"<p>Le stade SIDA est défini par la survenue d'une <strong>pathologie opportuniste classante</strong>. Bien que le taux de CD4 ne fasse pas partie intrinsèquement de la définition, le SIDA survient le plus souvent lorsque le taux de CD4 est inférieur à <strong>200/mm³</strong>. Une fois le stade SIDA atteint, il est maintenu définitivement, même après une remontée des CD4 sous traitement.</p>"},{"i":"9b0347bad4e3","n":169,"o":"169-5","u":"Diagnostic positif","t":"Connaître les signes évocateurs de primo infection, phase chronique et SIDA","q":"Quels sont les signes cliniques d'immunodépression débutante pouvant survenir lors de la phase chronique du VIH ?","a":"<p>Bien que souvent asymptomatique, la phase chronique du VIH peut présenter des signes d'immunodépression débutante tels que :</p><ul><li>La <strong>candidose buccale</strong>.</li><li>La <strong>leucoplasie chevelue de la langue</strong>.</li><li>Le <strong>zona du sujet jeune</strong>.</li><li>La <strong>dermite séborrhéique</strong>.</li><li>Une altération de l'état général (AEG).</li><li>Des <strong>sueurs nocturnes</strong>.</li><li>Des <strong>polyadénopathies persistantes</strong>.</li></ul>"},{"i":"eda51b3e6192","n":169,"o":"169-5","u":"Diagnostic positif","t":"Connaître les signes évocateurs de primo infection, phase chronique et SIDA","q":"Quelle est la conduite à tenir diagnostique devant une suspicion de primo-infection VIH avec un test ELISA négatif ?","a":"<p>Devant la suspicion d'une primo-infection VIH (fièvre + exanthème + polyadénopathies + pharyngite chez un sujet à risque) et un test ELISA négatif, il faut malgré tout <strong>évoquer une primo-infection VIH</strong>. Le test ELISA peut être négatif car la séroconversion n'est pas encore faite. Il est alors nécessaire de réaliser une <strong>PCR ARN-VIH</strong> pour confirmer le diagnostic.</p>"},{"i":"f8e7a898cfb6","n":169,"o":"169-5","u":"Diagnostic positif","t":"Connaître les signes évocateurs de primo infection, phase chronique et SIDA","q":"Quelles sont les anomalies biologiques évocatrices d'une primo-infection VIH ?","a":"<p>Les anomalies biologiques qui peuvent évoquer une primo-infection VIH sont :</p><ul><li>Une <strong>thrombopénie</strong> (75%)</li><li>Une <strong>inversion du rapport CD4/CD8</strong>.</li><li>Une <strong>cytolyse hépatique</strong>.</li><li>Une <strong>hypergammaglobulinémie polyclonale</strong>.</li></ul>"},{"i":"3e86a681e60e","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"Quelles sont les infections opportunistes classantes du VIH survenant à des seuils de CD4 inférieurs à 100/mm³ ?","a":"<ul><li>La <strong>cryptococcose neuroméningée</strong></li><li>La <strong>LEMP</strong> (Leucoencéphalopathie multifocale progressive)</li><li>Le <strong>lymphome cérébral primitif</strong></li></ul>"},{"i":"5ceb7a8c2513","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"À quel seuil de CD4 les candidoses orales, la tuberculose, la maladie de Kaposi, le zona et le lymphome non hodgkinien sont-ils des infections opportunistes classantes chez un patient VIH ?","a":"<p>Ces infections opportunistes (IO) sont classantes pour le VIH quand le taux de CD4 est compris entre <strong>200 et 500/mm³</strong>.</p>"},{"i":"752220863991","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"Quels sont les signes cliniques caractéristiques d'une pneumocystose chez un patient VIH ?","a":"<p>Une pneumocystose se caractérise par une <strong>toux sèche</strong>, une <strong>dyspnée progressive</strong> sur 2-3 semaines, et une <strong>hypoxémie disproportionnée</strong> par rapport à une auscultation pulmonaire généralement pauvre.</p>"},{"i":"7f1ce09c6ced","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"Quels sont les signes d'appel d'une candidose œsophagienne chez un séropositif VIH ?","a":"<p>Une candidose œsophagienne se manifeste par une <strong>odynophagie</strong>, souvent associée à un <strong>muguet oral</strong>.</p>"},{"i":"81bed4ba00f4","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"Comment se manifeste cliniquement une toxoplasmose cérébrale chez un patient infecté par le VIH ?","a":"<p>La toxoplasmose cérébrale se manifeste par des <strong>céphalées</strong>, de la <strong>fièvre</strong> et un <strong>syndrome focal</strong>, tel qu'une hémiparésie ou des crises comitiales.</p>"},{"i":"a5b702eba856","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"Quels sont les tableaux cliniques des infections opportunistes survenant à un seuil de CD4 inférieur à 50/mm³ chez un patient VIH ?","a":"<ul><li><strong>Infection à CMV</strong> (cytomégalovirus) : généralement responsable d'une <strong>rétinite</strong> qui se manifeste par une baisse d'acuité visuelle unilatérale progressive.</li><li><strong><br>Mycobacterium avium complex</strong> (MAC) : ces mycobactéries atypiques peuvent provoquer des infections disséminées.</li></ul>"},{"i":"ad569a896436","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"Comment se présente cliniquement la cryptococcose neuroméningée chez un patient infecté par le VIH ?","a":"<p>La cryptococcose neuroméningée se caractérise par des <strong>céphalées subaiguës</strong> et un <strong>syndrome méningé fruste</strong>.</p>"},{"i":"f0ba8efecd36","n":169,"o":"169-7","u":"Diagnostic positif","t":"Connaître les principales IO, tableaux cliniques, situation de survenue (taux de CD4)","q":"Quelles infections opportunistes sont classantes pour le VIH lorsque le taux de CD4 est inférieur à 200/mm³ ?","a":"<ul><li>La <strong>pneumocystose pulmonaire</strong></li><li>La <strong>toxoplasmose cérébrale</strong></li><li>La <strong>candidose œsophagienne</strong></li></ul>"}]};